window.__IM_G6_UNITS__[6] = {"schemaVersion":"1.0.0","number":6,"code":"unit06","title":"6.6 Expressions and Equations","bilingual":{"titleVi":"Biểu Thức & Phương Trình (Expressions and Equations)","summaryVi":"Giải phương trình một ẩn (x + p = q và px = q) bằng sơ đồ băng giấy (Tape Diagram) và cân thăng bằng (Hanger Diagram), tính chất phân phối, lũy thừa (Exponents) và biểu diễn mối quan hệ giữa 2 đại lượng trên đồ thị.","cues":[{"en":"equivalent expressions","vi":"Hai biểu thức tương đương (luôn có cùng giá trị với mọi x)","math":"2(x+3) = 2x+6"},{"en":"distributive property","vi":"Tính chất phân phối","math":"a(b+c) = ab+ac"},{"en":"dependent / independent variable","vi":"Biến phụ thuộc (y) / Biến độc lập (x)","math":"y = f(x)"}],"trapsVi":["Trong phương trình cân bằng (Balanced Hanger), bạn bỏ bớt hay chia đều bên trái bao nhiêu thì PHẢI làm y hệt ở bên phải."]},"totalActivities":56,"totalProblems":121,"lessons":[{"uid":"img6.u06.l01","number":1,"title":"Tape Diagrams and Equations","introText":"Let's see how tape diagrams and equations can show relationships between amounts.","activities":[{"title":"1.1: Which Diagram is Which?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Here are two diagrams. One represents <span class=\"math math-repaired\" data-png-file-id=\"3473\">\\(2+5=7\\)</span>. The other represents <span class=\"math math-repaired\" data-png-file-id=\"42813\">\\(5 \\boldcdot 2=10\\)</span>. Which is which? Label the length of each diagram.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27755\" data-record-model=\"ImageFile\"><img alt=\"Two tape diagrams. Tape diagram on the left, 5 equal parts labeled 2. Total, blank box with dotted sides. Tape diagram on the right, 2 parts, labeled 2, 5. Total, blank box with dotted sides.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KgzrxSzFdLytgsyd185sWK5k\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Draw a diagram that represents each equation.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                        <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"3462\">\\(4+3=7\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                        <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"3463\">\\(4 \\boldcdot 3=12\\)</span></p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n              </ol>\n            </div>"},{"title":"1.2: Match Equations and Tape Diagrams","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are two tape diagrams. Match each equation to one of the tape diagrams.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27758\" data-record-model=\"ImageFile\"><img alt=\"Two tape diagram. Tape diagram on the left, 2 parts labeled 4, x. Total, 12. Tape diagram on the right, 4 equal parts, labeled x. Total, 12.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/rp8yLV7xgazfXg7SPdLVFvST\">\n                \n              </figure>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <ul>\n                      <li><span class=\"math math-repaired\">\\(4 + x = 12\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(12 \\div 4 = x\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(4 \\boldcdot x = 12\\)</span></li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <ul>\n                      <li><span class=\"math math-repaired\">\\(12 = 4 + x\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(12 - x = 4\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(12 = 4 \\boldcdot x\\)</span></li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                    <ul>\n                      <li><span class=\"math math-repaired\">\\(12 - 4 = x\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(x = 12 - 4\\)</span></li>\n                      <li><span class=\"math math-repaired\">\\(x+x+x+x=12\\)</span></li>\n                    </ul>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"1.3: Draw Diagrams for Equations","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each equation, draw a diagram and find the value of the unknown that makes the equation true.</p>\n              <ol>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"41380\">\\(18 = 3+x\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"3486\">\\(18 = 3 \\boldcdot y\\)</span>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>You are walking down a road, seeking treasure. The road branches off into three paths. A guard stands in each path. You know that only one of the guards is telling the truth, and the other two are lying. Here is what they say:</p>\n                    <ul class=\"list--compressed\">\n                      <li>Guard 1: The treasure lies down this path.</li>\n                      <li>Guard 2: No treasure lies down this path; seek elsewhere.</li>\n                      <li>Guard 3: The first guard is lying.</li>\n                    </ul>\n                    <p>Which path leads to the treasure?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Tape diagrams can help us understand relationships between quantities and how operations describe those relationships.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26868\" data-record-model=\"ImageFile\"><img alt=\"Two tape diagrams, labeled A and B. Tape diagram A, 3 equal parts labeled x, x, x. Total, 21. Tape diagram B, 2 parts, labeled y, 3. Total, 21.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/WsojFDc2HtPMvST5i2sYQnUm\">\n                \n              </figure>\n              <p>Diagram A has 3 parts that add to 21. Each part is labeled with the same letter, so we know the three parts are equal. Here are some equations that all represent diagram A:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x+x+x=21\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle 3\\boldcdot {x}=21\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=21\\div3\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=\\frac13\\boldcdot {21}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                    <p>Notice that the number 3 is not seen in the diagram; the 3 comes from counting 3 boxes representing 3 equal parts in 21.</p>\n                    <p>We can use the diagram or any of the equations to reason that the value of <span class=\"math math-repaired\">\\(x\\)</span> is 7.</p>\n                  </div>\n                </div>\n              </div>\n              <p>Diagram B has 2 parts that add to 21. Here are some equations that all represent diagram B:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle y+3=21\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle y=21-3\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle 3=21-y\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                    <p>We can use the diagram or any of the equations to reason that the value of <span class=\"math math-repaired\">\\(y\\)</span> is 18.</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Here is an equation: <span class=\"math math-repaired\" data-png-file-id=\"35956\">\\(x + 4 = 17\\)</span></p>\n            <ol>\n              <li>Draw a tape diagram to represent the equation.\n              </li>\n              <li>Which part of the diagram shows the quantity <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>? What about 4? What about 17?\n              </li>\n              <li>How does the diagram show that <span class=\"math math-repaired\" data-png-file-id=\"2471\">\\(x+4\\)</span> has the same value as 17?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Diego is trying to find the value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> in <span class=\"math math-repaired\" data-png-file-id=\"35949\">\\(5 \\boldcdot x = 35\\)</span>. He draws this diagram but is not certain how to proceed.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-fourth g--row-1\">\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29587\" data-record-model=\"ImageFile\"><img alt=\"Tape diagram. 5 equal parts labeled x, x, x, x, x. \" class=\"h-max-height--2-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/4VGXNLeBYZUek9zDvoTh36ig\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-3 g--column g--content g--one-fourth g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n            <ol>\n              <li>Complete the tape diagram so it represents the equation <span class=\"math math-repaired\" data-png-file-id=\"35949\">\\(5 \\boldcdot x = 35\\)</span>.</li>\n              <li>Find the value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Match each equation to one of the two tape diagrams.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"35954\">\\(x + 3 = 9\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"35986\">\\(3 \\boldcdot x = 9\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"13290\">\\(9=3 \\boldcdot x\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"36028\">\\(3+x=9\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"36067\">\\(x = 9 - 3\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"36122\">\\(x = 9 \\div 3\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"36179\">\\(x + x+ x = 9\\)</span></li>\n                  </ol>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29585\" data-record-model=\"ImageFile\"><img alt=\"Two tape diagrams, A and B. A, 3 equal parts labeled, x. Total, 9. B, 2 parts labeled x and 3. Total, 9.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/GH9DyQppzsfn3ziFDhzassX3\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>For each equation, draw a tape diagram and find the unknown value.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35957\">\\(x+9=16\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35993\">\\(4 \\boldcdot x = 28\\)</span></p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>A shopper paid <span>$</span>2.52 for 4.5 pounds of potatoes, <span>$</span>7.75 for 2.5 pounds of broccoli, and <span>$</span>2.45 for 2.5 pounds of pears. What is the unit price of each item she bought? Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>A sports drink bottle contains 16.9 fluid ounces. Andre drank 80% of the bottle. How many fluid ounces did Andre drink? Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 14.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>The daily recommended allowance of calcium for a sixth grader is 1,200 mg. One cup of milk has 25% of the recommended daily allowance of calcium. How many milligrams of calcium are in a cup of milk? If you get stuck, consider using the double number line.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29511\" data-record-model=\"ImageFile\"><img alt=\"A double number line.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/k9aNYe3EkGX3VZoQmLExzLXM\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 11.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l02","number":2,"title":"Truth and Equations","introText":"Let's use equations to represent stories and see what it means to solve equations.","activities":[{"title":"2.1: Three Letters","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>The equation <span class=\"math math-repaired\" data-png-file-id=\"14474\">\\(a + b = c\\)</span> could be true or false.</p>\n                  <ol>\n                    <li>If <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> is 3, <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> is 4, and <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> is 5, is the equation true or false?\n                    </li>\n                    <li>Find new values of <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>, and <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> that make the equation true.\n                    </li>\n                    <li>Find new values of <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>, and <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> that make the equation false.\n                    </li>\n                  </ol>\n                </li>\n                <li>\n                  <p>The equation <span class=\"math math-repaired\" data-png-file-id=\"41301\">\\(x \\boldcdot y = z\\)</span> could be true or false.</p>\n                  <ol>\n                    <li>If <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is 4, and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span> is 12, is the equation true or false?\n                    </li>\n                    <li>Find new values of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>, and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span> that make the equation true.\n                    </li>\n                    <li>Find new values of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>, and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span> that make the equation false.\n                    </li>\n                  </ol>\n                </li>\n              </ol>\n            </div>"},{"title":"2.2: Storytime","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are three situations and six equations. Which equation best represents each situation? If you get stuck, consider drawing a diagram.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"42847\">\\(x + 5 = 20\\)</span></p>\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"42879\">\\(x + 20 = 5\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"42909\">\\(x = 20 + 5\\)</span></p>\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"42943\">\\(5\\boldcdot {20} = x\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"42984\">\\(5x=20\\)</span></p>\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"43023\">\\(20x = 5\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <ol>\n                <li>\n                  <p>After Elena ran 5 miles on Friday, she had run a total of 20 miles for the week. She ran <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> miles before Friday.</p>\n                </li>\n                <li>\n                  <p>Andre’s school has 20 clubs, which is five times as many as his cousin’s school. His cousin’s school has <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> clubs.</p>\n                </li>\n                <li>Jada volunteers at the animal shelter. She divided 5 cups of cat food equally to feed 20 cats. Each cat received <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> cups of food.\n                </li>\n              </ol>\n            </div>"},{"title":"2.3: Using Structure to Find Solutions","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are some equations that contain a <strong>variable</strong> and a list of values. Think about what each equation means and find a <strong>solution</strong> in the list of values. If you get stuck, consider drawing a diagram. Be prepared to explain why your solution is correct.</p>\n              <ol>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43044\">\\(1000 - a = 400\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"3493\">\\(12.6 = b + 4.1\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43082\">\\(8c = 8\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43122\">\\(\\frac23 \\boldcdot d = \\frac{10}{9}\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43159\">\\(10e = 1\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43200\">\\(10 = 0.5f\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43235\">\\(0.99 = 1 - g\\)</span>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"43277\">\\(h + \\frac 3 7 = 1\\)</span>\n                </li>\n              </ol>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--content g--col-1 g--row-1 g--one-twelfth\">\n                    <p>List:</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-2 g--row-1 g--one-twelfth\">\n                    <p> <span class=\"math math-repaired\" data-png-file-id=\"2240\">\\(\\frac18\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-3 g--row-1 g--one-twelfth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"4773\">\\(\\frac37\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-4 g--row-1 g--one-twelfth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"5308\">\\(\\frac47\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-5 g--row-1 g--one-twelfth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"3317\">\\(\\frac35\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-6 g--row-1 g--one-twelfth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"11218\">\\(\\frac53\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-7 g--row-1 g--one-twelfth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36631\">\\(\\frac73\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-8 g--row-1 g--one-twelfth\">\n                    <p>0.01</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-9 g--row-1 g--one-twelfth\">\n                    <p>0.1</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-10 g--row-1 g--one-twelfth\">\n                    <p>0.5</p>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--column g--content g--col-1 g--row-2 g--one-twelfth\">\n                    \n                  </div>\n                  <div class=\"g--column g--content g--col-2 g--row-2 g--one-twelfth\">\n                    <p>1</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-3 g--row-2 g--one-twelfth\">\n                    <p>2</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-4 g--row-2 g--one-twelfth\">\n                    <p>8.5</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-5 g--row-2 g--one-twelfth\">\n                    <p>9.5</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-6 g--row-2 g--one-twelfth\">\n                    <p>16.7</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-7 g--row-2 g--one-twelfth\">\n                    <p>20</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-8 g--row-2 g--one-twelfth\">\n                    <p>400</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-9 g--row-2 g--one-twelfth\">\n                    <p>600</p>\n                  </div>\n                  <div class=\"g--column g--content g--col-10 g--row-2 g--one-twelfth\">\n                    <p>1400</p>\n                  </div>\n                </div>\n              </div>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>One solution to the equation <span class=\"math math-repaired\" data-png-file-id=\"42852\">\\(a+b+c=10\\)</span> is <span class=\"math math-repaired\" data-png-file-id=\"3659\">\\(a=2\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"2552\">\\(b=5\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"13314\">\\(c=3\\)</span>. </p>\n                    <p>How many different whole-number solutions are there to the equation <span class=\"math math-repaired\" data-png-file-id=\"42852\">\\(a+b+c=10\\)</span>? Explain or show your reasoning.</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>An equation can be true or false. An example of a true equation is <span class=\"math math-repaired\">\\(7+1=4 \\boldcdot 2\\)</span>. An example of a false equation is <span class=\"math math-repaired\">\\(7+1=9\\)</span>. </p>\n              <p>An equation can have a letter in it, for example, <span class=\"math math-repaired\">\\(u+1=8\\)</span>. This equation is false if <span class=\"math math-repaired\">\\(u\\)</span> is 3, because <span class=\"math math-repaired\">\\(3+1\\)</span> does not equal 8. This equation is true if <span class=\"math math-repaired\">\\(u\\)</span> is 7, because <span class=\"math math-repaired\">\\(7+1=8\\)</span>.</p>\n              <p>A letter in an equation is called a <strong>variable</strong>. In <span class=\"math math-repaired\">\\(u+1=8\\)</span>, the variable is <span class=\"math math-repaired\">\\(u\\)</span>. A number that can be used in place of the variable that makes the equation true is called a <strong>solution</strong> to the equation. In <span class=\"math math-repaired\">\\(u+1=8\\)</span>, the solution is 7.</p>\n              <p>When a number is written next to a variable, the number and the variable are being multiplied. For example, <span class=\"math math-repaired\">\\(7x=21\\)</span> means the same thing as <span class=\"math math-repaired\">\\(7 \\boldcdot x = 21\\)</span>. A number written next to a variable is called a <strong>coefficient</strong>. If no coefficient is written, the coefficient is 1. For example, in the equation <span class=\"math math-repaired\">\\(p+3=5\\)</span>, the coefficient of <span class=\"math math-repaired\">\\(p\\)</span> is 1.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the true equations.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(5 + 0 = 0\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(15 \\boldcdot 0 = 0\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(1.4 + 2.7 = 4.1\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(\\frac{2}{3} \\boldcdot \\frac{5}{9} = \\frac{7}{12}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(4 \\frac{2}{3}=5 - \\frac{1}{3}\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Mai's water bottle had 24 ounces in it. After she drank <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> ounces of water, there were 10 ounces left. Select <strong>all</strong> the equations that represent this situation.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(24 \\div 10 = x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(24 +10 = x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(24 - 10 = x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(x + 10 = 24\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(10x = 24\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Priya has 5 pencils, each <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> inches in length. When she lines up the pencils end to end, they measure 34.5 inches. Select <strong>all</strong> the equations that represent this situation.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(5 + x = 34.5\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(5x = 34.5\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(34.5 \\div 5 = x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(34.5 - 5 = x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(x = (34.5) \\boldcdot 5\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Match each equation with a solution from the list of values. </p>\n          </div>\n          <div class=\"im-c-columns\">\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">A: \n                <p><span class=\"math math-repaired\">\\(2a = 4.6\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">B: \n                <p><span class=\"math math-repaired\">\\(b + 2 = 4.6\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">C: \n                <p><span class=\"math math-repaired\">\\(c \\div 2 = 4.6\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">D: \n                <p><span class=\"math math-repaired\">\\(d - 2 = 4.6\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">E: \n                <p><span class=\"math math-repaired\">\\(e+\\frac{3}{8} = 2\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">F: \n                <p><span class=\"math math-repaired\">\\(\\frac{1}{8}f = 3\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">G: \n                <p><span class=\"math math-repaired\">\\(g \\div \\frac{8}{5} = 1\\)</span></p>\n              </div>\n            </section>\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">1: \n                <p><span class=\"math math-repaired\">\\(\\frac{8}{5}\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">2: \n                <p><span class=\"math math-repaired\">\\(1 \\frac{5}{8}\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">3: \n                <p>2.3</p>\n              </div>\n              <div class=\"im-c-content\">4: \n                <p>2.6</p>\n              </div>\n              <div class=\"im-c-content\">5: \n                <p>6.6</p>\n              </div>\n              <div class=\"im-c-content\">6: \n                <p>9.2</p>\n              </div>\n              <div class=\"im-c-content\">7: \n                <p>24</p>\n              </div>\n            </section>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>The daily recommended allowance of vitamin C for a sixth grader is 45 mg. 1 orange has about 75% of the recommended daily allowance of vitamin C. How many milligrams are in 1 orange? If you get stuck, consider using the double number line.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29514\" data-record-model=\"ImageFile\"><img alt=\"Double number line. Vitamin C in mg. Percentage.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/tbCB4RhjVuXmrDsr7DrCn9R5\">\n              \n            </figure>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 11.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>There are 90 kids in the band. 20% of the kids own their own instruments, and the rest rent them.</p>\n            <ol>\n              <li>How many kids own their own instruments?\n              </li>\n              <li>How many kids rent instruments?\n              </li>\n              <li>What percentage of kids rent their instruments?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 12.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Find each product.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35783\">\\((0.25) \\boldcdot (1.4)\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"8203\">\\((0.061) \\boldcdot (0.43)\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35842\">\\((1.017) \\boldcdot (0.072)\\)</span>\n              </li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"35881\">\\((5.226) \\boldcdot (0.037)\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 8.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l03","number":3,"title":"Staying in Balance","introText":"Let's use balanced hangers to help us solve equations.","activities":[{"title":"3.1: Hanging Around","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27764\" data-record-model=\"ImageFile\"><img alt=\"Two hangers, A and B. A, unbalanced. B, balanced.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/hnHyZ2WVmPHR2SoetbCheWwm\">\n                \n              </figure>\n              <p>For diagram A, find:</p>\n              <ol>\n                <li>One thing that <em>must</em> be true\n                </li>\n                <li>One thing that <em>could</em> be true or false\n                </li>\n                <li>One thing that <em>cannot possibly</em> be true\n                </li>\n              </ol>\n              <p>For diagram B, find:</p>\n              <ol>\n                <li>One thing that <em>must</em> be true\n                </li>\n                <li>One thing that <em>could</em> be true or false\n                </li>\n                <li>One thing that <em>cannot possibly</em> be true\n                </li>\n              </ol>\n            </div>"},{"title":"3.2: Match Equations and Hangers","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27766\" data-record-model=\"ImageFile\"><img alt=\"Four balanced hangers, A, B, C, and D.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/mZCbi5Htnh4Qc2HLSHZdpjWk\">\n                \n              </figure>\n              <ol>\n                <li>\n                  <p>Match each hanger to an equation. Complete the equation by writing <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span>, or <span class=\"math math-repaired\" data-png-file-id=\"1277\">\\(w\\)</span> in the empty box.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--column g--one-fourth g--content g--col-1 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"42113\">\\(\\boxed{\\phantom{3}} + 3 = 6\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-2 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(3 \\boldcdot \\boxed{\\phantom{3}} = 6\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-3 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"42200\">\\(6 =\\boxed{\\phantom{3}} + 1\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-4 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"42237\">\\(6 = 3 \\boldcdot \\boxed{\\phantom{3}}\\)</span></p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>​​Find a solution to each equation. Use the hangers to explain what each solution means.\n                </li>\n              </ol>\n            </div>"},{"title":"3.3: Connecting Diagrams to Equations and Solutions","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here are some balanced hangers. Each piece is labeled with its weight.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27767\" data-record-model=\"ImageFile\"><img alt=\"Four balanced hangers, A, B, C, and D.\" class=\"h-max-height--12-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/gS9ZTa19DVBqg1CEXbK9YdvA\">\n                \n              </figure>\n              <p>For each diagram:</p>\n              <ol>\n                <li>Write an equation.\n                </li>\n                <li>\n                  <p>Explain how to reason with the <em>diagram</em> to find the weight of a piece with a letter.</p>\n                </li>\n                <li>\n                  <p>Explain how to reason with the <em>equation</em> to find the weight of a piece with a letter.</p>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>When you have the time, visit the site <a href=\"https://solveme.edc.org/Mobiles.html\">https://solveme.edc.org/Mobiles.html</a> to solve some trickier puzzles that use hanger diagrams like the ones in this lesson. You can even build new ones. (If you want to do this during class, check with your teacher first!)</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"318\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/505730840\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U6V1 Understanding Equations (Lessons 1–3)</em> available at <a href=\"https://player.vimeo.com/video/505730840\">https://player.vimeo.com/video/505730840</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the equations that represent the hanger.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29591\" data-record-model=\"ImageFile\"><img alt=\"Balanced hanger. Left side, 3 identical circles labeled, x. Right side, 6 identical squares.\" class=\"h-max-height--10-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/hgFo7pWL1wAtGVdF9qTXy373\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(x+x+x = 1+1+1+1+1+1\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(x \\boldcdot x \\boldcdot x = 6\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(3x = 6\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(x + 3 = 6\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(x \\boldcdot x \\boldcdot x = 1 \\boldcdot 1 \\boldcdot 1 \\boldcdot 1 \\boldcdot 1 \\boldcdot 1\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Write an equation to represent each hanger.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29594\" data-record-model=\"ImageFile\"><img alt=\"Four balanced hangers, A, B, C, and D.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/4oh2N5hoWqXjKx3HBPPExgYa\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                  <ol>\n                    <li>Write an equation to represent the hanger.<br>\n                       </li>\n                    <li>Explain how to reason with the hanger to find the value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.<br>\n                       \n                    </li>\n                    <li>Explain how to reason with the equation to find the value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.\n                    </li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29590\" data-record-model=\"ImageFile\"><img alt=\"Balanced hanger. Left side, 2 identical circles, x, right side, 1 rectangle, 14 point 6 2. \" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/MFZv37dmdfjqRYSejuPwjLXg\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Andre says that <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 7 because he can move the two 1s with the <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> to the other side.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29593\" data-record-model=\"ImageFile\"><img alt=\"Balanced hanger. Left side, 1 circle, x, 2 identical squares, 1, right side, five identical squares, 1.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/hNSg67HAhpa1t6s37zkyEohc\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                  <p>Do you agree with Andre? Explain your reasoning.</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Match each equation to one of the diagrams.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"10442\">\\(12-m=4\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"10456\">\\(12=4\\boldcdot m\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"10468\">\\(m-4=12\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"10478\">\\(\\frac{m}{4}=12\\)</span></li>\n            </ol>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29586\" data-record-model=\"ImageFile\"><img alt=\"Four tape diagrams labeled A, B, C, and D.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/xWZvhUQNKrVhtZMoBnWoRW76\">\n              \n            </figure>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 1.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>The area of a rectangle is 14 square units. It has side lengths <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>. Given each value for <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, find <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35591\">\\(x=2\\frac13\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35642\">\\(x=4\\frac15\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35673\">\\(x=\\frac76\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 4, Lesson 13.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Lin needs to save up <span>$</span>20 for a new game. How much money does she have if she has saved each percentage of her goal. Explain your reasoning.</p>\n            <ol>\n              <li>25%\n              </li>\n              <li>75%\n              </li>\n              <li>125%\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 11.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l04","number":4,"title":"Practice Solving Equations and Representing Situations with Equations","introText":"Let's solve equations by doing the same to each side.","activities":[{"title":"4.1: Number Talk: Subtracting From Five","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the value of each expression mentally.</p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"41218\">\\(5-2\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"41266\">\\(5-2.1\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"41308\">\\(5-2.17\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"41343\">\\(5-2\\frac78\\)</span></p>\n            </div>"},{"title":"4.2: Row Game: Solving Equations Practice","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Solve the equations in one column. Your partner will work on the other column.</p>\n              <p>Check in with your partner after you finish each row. Your answers in each row should be the same. If your answers aren’t the same, work together to find the error and correct it.</p>\n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">column A</th>\n                    <th scope=\"col\">column B</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42857\">\\(18=2x\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42894\">\\(36=4x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42923\">\\(17=x+9\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42964\">\\(13=x+5\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43000\">\\(8x=56\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43031\">\\(3x=21\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"3495\">\\(21=\\frac14 x\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43077\">\\(28=\\frac13 x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43112\">\\(6x=45\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43151\">\\(8x=60\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43189\">\\(x+4\\frac56=9\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43229\">\\(x+3\\frac56=8\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"3497\">\\(\\frac57x=55\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43270\">\\(\\frac37x=33\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43307\">\\(\\frac15=6x\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43338\">\\(\\frac13=10x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43377\">\\(2.17+x=5\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43416\">\\(6.17+x=9\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43470\">\\(\\frac{20}{3}=\\frac{10}{9}x\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43516\">\\(\\frac{14}{5}=\\frac{7}{15}x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43559\">\\(14.88+x=17.05\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43598\">\\(3.91+x=6.08\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43638\">\\(3\\frac34x=1\\frac14\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"43678\">\\(\\frac75x=\\frac{7}{15}\\)</span></td>\n                  </tr>\n                </tbody>\n              </table>\n              \n            </div>"},{"title":"4.3: Choosing Equations to Match Situations","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Circle <strong>all </strong>of the equations that describe each situation. If you get stuck, consider drawing a diagram. Then find the solution for each situation.</p>\n              <ol>\n                <li>\n                  <p>Clare has 8 fewer books than Mai. If Mai has 26 books, how many books does Clare have?</p>\n                  <ul class=\"list--compressed\">\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41432\">\\(26-x=8\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41466\">\\(x=26+8\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41504\">\\(x+8=26\\)</span></li>\n                    <li>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41544\">\\(26-8=x\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41580\">\\(x = \\text{______}\\)</span>\n                    </li>\n                  </ul>\n                </li>\n                <li>\n                  <p>A coach formed teams of 8 from all the players in a soccer league. There are 14 teams. How many players are in the league?</p>\n                  <ul class=\"list--compressed\">\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41617\">\\(y=14\\div8\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41658\">\\(\\frac{y}{8}=14\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41703\">\\(\\frac18y=14\\)</span></li>\n                    <li>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41747\">\\(y=14\\boldcdot 8\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41793\">\\(y = \\text{______}\\)</span>\n                    </li>\n                  </ul>\n                </li>\n                <li>\n                  <p>Kiran scored 223 more points in a computer game than Tyler. If Kiran scored 409 points, how many points did Tyler score?</p>\n                  <ul class=\"list--compressed\">\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41837\">\\(223=409-z\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41882\">\\(409-223=z\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"41933\">\\(409+223=z\\)</span></li>\n                    <li>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41978\">\\(409=223+z\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"42019\">\\(z = \\text{______}\\)</span>\n                    </li>\n                  </ul>\n                </li>\n                <li>\n                  <p>Mai ran 27 miles last week, which was three times as far as Jada ran. How far did Jada run?</p>\n                  <ul class=\"list--compressed\">\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"42066\">\\(3w=27\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"42108\">\\(w=\\frac13\\boldcdot 27\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"42150\">\\(w=27\\div3\\)</span></li>\n                    <li>\n                      <span class=\"math math-repaired\" data-png-file-id=\"42190\">\\(w=3\\boldcdot 27\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"42221\">\\(w = \\text{______}\\)</span>\n                    </li>\n                  </ul>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Mai’s mother was 28 when Mai was born. Mai is now 12 years old. In how many years will Mai’s mother be twice Mai’s age? How old will they be then?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Writing and solving equations can help us answer questions about situations.</p>\n              <p>Suppose a scientist has 13.68 liters of acid and needs 16.05 liters for an experiment. How many more liters of acid does she need for the experiment?</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <ul>\n                      <li>We can represent this situation with the equation:</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle 13.68 + x=16.05\\)</span></p>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--row-2 g--two-third\">\n                    <ul>\n                      <li>When working with hangers, we saw that the solution can be found by subtracting 13.68 from each side. This gives us some new equations that also represent the situation:</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=16.05 - 13.68\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=2.37\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <ul>\n                <li>Finding a solution in this way leads to a variable on one side of the equal sign and a number on the other. We can easily read the solution—in this case, 2.37—from an equation with a letter on one side and a number on the other. We often write solutions in this way.</li>\n              </ul>\n              <p>Let’s say a food pantry takes a 54-pound bag of rice and splits it into portions that each weigh <span class=\"math math-repaired\">\\(\\frac34\\)</span> of a pound. How many portions can they make from this bag?</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <ul>\n                      <li>We can represent this situation with the equation:</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle \\frac34 x = 54\\)</span></p>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--row-2 g--two-third\">\n                    <ul>\n                      <li>We can find the value of <span class=\"math math-repaired\">\\(x\\)</span> by dividing each side by <span class=\"math math-repaired\">\\(\\frac34\\)</span>. This gives us some new equations that represent the same situation:</li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=54\\div \\frac34\\)</span></p>\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x=72\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <ul>\n                <li>The solution is 72 portions.</li>\n              </ul>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the equations that describe each situation and then find the solution.</p>\n            <ol>\n              <li>\n                <p>Kiran’s backpack weighs 3 pounds less than Clare’s backpack. Clare’s backpack weighs 14 pounds. How much does Kiran’s backpack weigh?</p>\n                <ul class=\"list--compressed\">\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36002\">\\(x+3=14\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36040\">\\(3x=14\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36086\">\\(x = 14 -3\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36145\">\\(x = 14 \\div 3\\)</span></p>\n                  </li>\n                </ul>\n              </li>\n              <li>\n                <p>Each notebook contains 60 sheets of paper. Andre has 5 notebooks. How many sheets of paper do Andre’s notebooks contain?</p>\n                <ul class=\"list--compressed\">\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36200\">\\(y = 60 \\div 5\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36241\">\\( y = 5 \\boldcdot 60\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36285\">\\(\\frac{y}{5} = 60\\)</span></p>\n                  </li>\n                  <li>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"36333\">\\(5y = 60\\)</span></p>\n                  </li>\n                </ul>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Solve each equation.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"18165\">\\(2x = 5\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36008\">\\(y + 1.8 = 14.7\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36048\">\\(6 = \\frac{1}{2} z\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36089\">\\(3\\frac{1}{4} = \\frac{1}{2} + w\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36142\">\\(2.5t = 10\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>For each equation, draw a tape diagram that represents the equation.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35951\">\\(3\\boldcdot x = 18\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36007\">\\(3+x=18\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36044\">\\(17 - 6 = x\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 1.)</span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Find each product.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"35789\">\\((21.2)\\boldcdot (0.02)\\)</span></p>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"35841\">\\((2.05)\\boldcdot (0.004)\\)</span></p>\n                </div>\n              </div>\n            </div>\n            \n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 8.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>For a science experiment, students need to find 25% of 60 grams.</p>\n            <ul class=\"list--compressed\">\n              <li>Jada says, “I can find this by calculating <span class=\"math math-repaired\" data-png-file-id=\"451\">\\(\\frac{1}{4}\\)</span> of 60.”</li>\n              <li>Andre says, “25% of 60 means <span class=\"math math-repaired\" data-png-file-id=\"35406\">\\(\\frac{25}{100} \\boldcdot 60\\)</span>.”</li>\n            </ul>\n            <p>Do you agree with either of them? Explain your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 13.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l05","number":5,"title":"A New Way to Interpret $a$ over $b$","introText":"Let's investigate what a fraction means when the numerator and denominator are not whole numbers.","activities":[{"title":"5.1: Recalling Ways of Solving","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Solve each equation. Be prepared to explain your reasoning.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41241\">\\(0.07 = 10m\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41283\">\\(10.1 = t + 7.2\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"5.2: Interpreting $\\frac{a}{b}$","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Solve each equation.</p>\n              <ol>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"39818\">\\(35=7x\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"39852\">\\(35=11x\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"39888\">\\(7x=7.7\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"39923\">\\(0.3x=2.1\\)</span></p>\n                </li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39963\">\\(\\frac25=\\frac12 x\\)</span>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Solve the equation. Try to find some shortcuts.</p>\n                    <p><span class=\"math math-displayed math-repaired\" data-png-file-id=\"failed-conversion\">\\(\\displaystyle \\frac{1}{6} \\boldcdot  \\frac{3}{20} \\boldcdot  \\frac{5}{42} \\boldcdot  \\frac{7}{72} \\boldcdot x = \\frac{1}{384}\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"5.3: Storytime Again","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Take turns with your partner telling a story that might be represented by each equation. Then, for each equation, choose one story, state what quantity <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> describes, and solve the equation. If you get stuck, consider drawing a diagram.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"41273\">\\(0.7 + x = 12\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\" data-png-file-id=\"41316\">\\(\\frac{1}{4}x = \\frac32\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              \n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>In the past, you learned that a fraction such as <span class=\"math math-repaired\">\\(\\frac45\\)</span> can be thought of in a few ways. </p>\n              <ul>\n                <li>\n                  <span class=\"math math-repaired\">\\(\\frac45\\)</span> is a number you can locate on the number line by dividing the section between 0 and 1 into 5 equal parts and then counting 4 of those parts to the right of 0.</li>\n                <li>\n                  <span class=\"math math-repaired\">\\(\\frac45\\)</span> is the share that each person would have if 4 wholes were shared equally among 5 people. This means that <span class=\"math math-repaired\">\\(\\frac45\\)</span> is the result of <em>dividing</em> 4 by 5.</li>\n              </ul>\n              <p>We can extend this meaning of <em>a fraction as a quotient</em> to fractions whose numerators and denominators are not whole numbers. For example, we can represent 4.5 pounds of rice divided into portions that each weigh 1.5 pounds as: <span class=\"math math-repaired\">\\(\\frac{4.5}{1.5} = 4.5\\div{1.5} = 3\\)</span>. In other words, <span class=\"math math-repaired\">\\(\\frac{4.5}{1.5}=3\\)</span> because the quotient of 4.5 and 1.5 is 3.</p>\n              <p>Fractions that involve non-whole numbers can also be used when we solve equations. </p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <p>Suppose a road under construction is <span class=\"math math-repaired\">\\(\\frac38\\)</span> finished and the length of the completed part is <span class=\"math math-repaired\">\\(\\frac43\\)</span> miles. How long will the road be when completed?</p>\n                    <p>We can write the equation <span class=\"math math-repaired\">\\(\\frac38x=\\frac43\\)</span> to represent the situation and solve the equation.</p>\n                    <p>The completed road will be <span class=\"math math-repaired\">\\(3\\frac59\\)</span> or about 3.6 miles long.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle \\begin {align} \\frac38x&amp;=\\frac43\\\\[5pt] x&amp;=\\frac{\\frac43}{\\frac38}\\\\[5pt] x&amp;=\\frac43\\boldcdot \\frac83\\\\[5pt] x&amp;=\\frac{32}{9}=3\\frac59\\\\ \\end {align}\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that equal <span class=\"math math-repaired\" data-png-file-id=\"36012\">\\(\\frac{3.15}{0.45}\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\((3.15) \\boldcdot (0.45)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\((3.15) \\div (0.45)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\((3.15) \\boldcdot \\frac{1}{0.45}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\((3.15) \\div \\frac{45}{100}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\((3.15) \\boldcdot \\frac{100}{45}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(\\frac{0.45}{3.15}\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Which expressions are solutions to the equation <span class=\"math math-repaired\" data-png-file-id=\"36013\">\\(\\frac{3}{4}x = 15\\)</span>? Select <strong>all</strong> that apply.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(\\frac{15}{\\frac{3}{4}}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(\\frac{15}{\\frac{4}{3}}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(\\frac{4}{3} \\boldcdot 15\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(\\frac{3}{4} \\boldcdot 15\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(15 \\div \\frac{3}{4}\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Solve each equation.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-fourth g--content g--col-1 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36014\">\\(4a = 32\\)</span></p>\n                </div>\n                <div class=\"g--column g--one-fourth g--content g--col-2 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36049\">\\(4=32b\\)</span></p>\n                </div>\n                <div class=\"g--column g--one-fourth g--content g--col-3 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36093\">\\(10c = 26\\)</span></p>\n                </div>\n                <div class=\"g--column g--one-fourth g--content g--col-4 g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36154\">\\(26=100d\\)</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>For each equation, write a story problem represented by the equation. For each equation, state what quantity <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> represents. If you get stuck, consider drawing a diagram.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36011\">\\(\\frac{3}{4} + x = 2\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36047\">\\(1.5x = 6\\)</span></p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Write as many mathematical expressions or equations as you can about the image. Include a fraction, a decimal number, or a percentage in each.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--two-third g--content g--col-1 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29518\" data-record-model=\"ImageFile\"><img alt=\"A fundraiser thermometer.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/7jxTGj2QTr975XqotYSCDTc6\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--column g--one-third g--content g--col-2 g--row-1\"></div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 13.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>In a lilac paint mixture, 40% of the mixture is white paint, 20% is blue, and the rest is red. There are 4 cups of blue paint used in a batch of lilac paint.</p>\n            <ol>\n              <li>How many cups of white paint are used?\n              </li>\n              <li>How many cups of red paint are used?\n              </li>\n              <li>How many cups of lilac paint will this batch yield?\n              </li>\n            </ol>\n            <p>If you get stuck, consider using a tape diagram.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 12.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Triangle P has a base of 12 inches and a corresponding height of 8 inches. Triangle Q has a base of 15 inches and a corresponding height of 6.5 inches. Which triangle has a greater area? Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 1, Lesson 9.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l06","number":6,"title":"Write Expressions Where Letters Stand for Numbers","introText":"Let's use expressions with variables to describe situations.","activities":[{"title":"6.1: Algebra Talk: When $x$ is 6","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>If <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 6, what is:</p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"29194\">\\(x + 4\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"42138\">\\(7 - x\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"1244\">\\(x^2\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"42181\">\\(\\frac13 x\\)</span></p>\n            </div>"},{"title":"6.2: Lemonade Sales and Heights","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Lin set up a lemonade stand. She sells the lemonade for <span>$</span>0.50 per cup.</p>\n                  <ol>\n                    <li>\n                      <p>Complete the table to show how much money she would collect if she sold each number of cups.</p>\n                      <table border=\"1\">\n                        <thead>\n                          <tr>\n                            <th scope=\"col\">lemonade sold (number of cups)</th>\n                            <td scope=\"col\" style=\"width:80px\">12</td>\n                            <td scope=\"col\" style=\"width:80px\">183</td>\n                            <td scope=\"col\" style=\"width:80px\"><span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span></td>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          <tr>\n                            <th scope=\"col\">money collected (dollars)</th>\n                            <td></td>\n                            <td></td>\n                            <td></td>\n                          </tr>\n                        </tbody>\n                      </table>\n                    </li>\n                    <li>How many cups did she sell if she collected <span>$</span>127.50? Be prepared to explain your reasoning.\n                    </li>\n                  </ol>\n                </li>\n                <li>\n                  <p>Elena is 59 inches tall. Some other people are taller than Elena. </p>\n                  <ol>\n                    <li>\n                      <p>Complete the table to show the height of each person.</p>\n                      <table border=\"1\">\n                        <thead>\n                          <tr>\n                            <th scope=\"col\">person</th>\n                            <th scope=\"col\" style=\"width:80px\">Andre</th>\n                            <th scope=\"col\" style=\"width:80px\">Lin</th>\n                            <th scope=\"col\" style=\"width:80px\">Noah</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          <tr>\n                            <th scope=\"col\">how much taller than Elena (inches)</th>\n                            <td>4</td>\n                            <td><span class=\"math math-repaired\" data-png-file-id=\"41253\">\\(6 \\frac12\\)</span></td>\n                            <td><span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span></td>\n                          </tr>\n                          <tr>\n                            <th scope=\"col\">person's height (inches)</th>\n                            <td></td>\n                            <td></td>\n                            <td></td>\n                          </tr>\n                        </tbody>\n                      </table>\n                    </li>\n                    <li>If Noah is <span class=\"math math-repaired\" data-png-file-id=\"41296\">\\(64 \\frac34\\)</span> inches tall, how much taller is he than Elena?\n                    </li>\n                  </ol>\n                </li>\n              </ol>\n            </div>"},{"title":"6.3: Building Expressions","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Clare is 5 years older than her cousin.</p>\n                  <ol>\n                    <li>\n                      <p>How old would Clare be if her cousin is:</p>\n                      <p>10 years old?</p>\n                      <p>2 years old?</p>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> years old?</p>\n                    </li>\n                    <li>Clare is 12 years old. How old is Clare’s cousin?\n                    </li>\n                  </ol>\n                </li>\n                <li>\n                  <p>Diego has 3 times as many comic books as Han.</p>\n                  <ol>\n                    <li>\n                      <p>How many comic books does Diego have if Han has:</p>\n                      <p>6 comic books?</p>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span> books?</p>\n                    </li>\n                    <li>Diego has 27 comic books. How many comic books does Han have?\n                    </li>\n                  </ol>\n                </li>\n                <li>\n                  <p>Two fifths of the vegetables in Priya’s garden are tomatoes.</p>\n                  <ol>\n                    <li>\n                      <p>How many tomatoes are there if Priya’s garden has:</p>\n                      <p>20 vegetables?</p>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> vegetables?</p>\n                    </li>\n                    <li>Priya’s garden has 6 tomatoes. How many total vegetables are there?\n                    </li>\n                  </ol>\n                </li>\n                <li>\n                  <p>A school paid <span>$</span>31.25 for each calculator.</p>\n                  <ol>\n                    <li>If the school bought <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> calculators, how much did they pay?\n                    </li>\n                    <li>The school spent <span>$</span>500 on calculators. How many did the school buy?\n                    </li>\n                  </ol>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Kiran, Mai, Jada, and Tyler went to their school carnival. They all won chips that they could exchange for prizes. Kiran won <span class=\"math math-repaired\" data-png-file-id=\"781\">\\(\\frac23\\)</span> as many chips as Jada. Mai won 4 times as many chips as Kiran. Tyler won half as many chips as Mai.</p>\n                    <ol>\n                      <li>Write an expression for the number of chips Tyler won. You should only use one variable: <span class=\"math math-repaired\" data-png-file-id=\"99\">\\(J\\)</span>, which stands for the number of chips Jada won.\n                      </li>\n                      <li>\n                        <p>If Jada won 42 chips, how many chips did Tyler, Kiran, and Mai each win?</p>\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Suppose you share a birthday with a neighbor, but she is 3 years older than you. When you were 1, she was 4. When you were 9, she was 12. When you are 42, she will be 45.</p>\n              <p>If we let <span class=\"math math-repaired\">\\(a\\)</span> represent your age at any time, your neighbor’s age can be expressed <span class=\"math math-repaired\">\\(a+3\\)</span>. </p>\n              <table border=\"1\">\n                <tbody>\n                  <tr>\n                    <th scope=\"col\">your age</th>\n                    <td> 1 </td>\n                    <td>9</td>\n                    <td>42</td>\n                    <td><span class=\"math math-repaired\">\\(a\\)</span></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"col\">neighbor's age</th>\n                    <td>4</td>\n                    <td>12</td>\n                    <td>45</td>\n                    <td><span class=\"math math-repaired\">\\(a+3\\)</span></td>\n                  </tr>\n                </tbody>\n              </table>\n              <p>We often use a letter such as <span class=\"math math-repaired\">\\(x\\)</span> or <span class=\"math math-repaired\">\\(a\\)</span> as a placeholder for a number in expressions. These are called <em>variables</em> (just like the letters we used in equations, previously). Variables make it possible to write expressions that represent a calculation even when we don't know all the numbers in the calculation. </p>\n              <p>How old will you be when your neighbor is 32? Since your neighbor's age is calculated with the expression <span class=\"math math-repaired\">\\(a+3\\)</span>, we can write the equation <span class=\"math math-repaired\">\\(a+3=32\\)</span>. When your neighbor is 32 you will be 29, because <span class=\"math math-repaired\">\\(a+3=32\\)</span> is true when <span class=\"math math-repaired\">\\(a\\)</span> is 29.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Instructions for a craft project say that the length of a piece of red ribbon should be 7 inches less than the length of a piece of blue ribbon.</p>\n            <ol>\n              <li>\n                <p>How long is the red ribbon if the length of the blue ribbon is:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p>10 inches?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p>27 inches?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> inches?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>How long is the blue ribbon if the red ribbon is 12 inches?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Tyler has 3 times as many books as Mai.</p>\n            <ol>\n              <li>\n                <p>How many books does Mai have if Tyler has:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p>15 books?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p>21 books?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> books?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Tyler has 18 books. How many books does Mai have?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>A bottle holds 24 ounces of water. It has <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> ounces of water in it.</p>\n            <ol>\n              <li>What does <span class=\"math math-repaired\" data-png-file-id=\"36020\">\\(24-x\\)</span> represent in this situation?\n              </li>\n              <li>Write a question about this situation that has <span class=\"math math-repaired\" data-png-file-id=\"36018\">\\(24-x\\)</span> for the answer.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Write an equation represented by this tape diagram using each of these operations.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29588\" data-record-model=\"ImageFile\"><img alt=\"Tape diagram. 3 equal parts labeled 9, 9, 9. Total, 27. \" class=\"h-max-height--3-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/MShoC8oVxXkanJjFC3t6bGN3\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                  <ol>\n                    <li>addition</li>\n                    <li>subtraction</li>\n                    <li>multiplication</li>\n                    <li>division</li>\n                  </ol>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 1.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the equations that describe each situation and then find the solution.</p>\n            <ol>\n              <li>\n                <p>Han's house is 450 meters from school. Lin’s house is 135 meters closer to school. How far is Lin’s house from school?</p>\n                <ul class=\"list--compressed\">\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36024\">\\(z = 450 + 135\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36059\">\\(z = 450-135\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36113\">\\(z-135 = 450\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36174\">\\(z + 135 = 450\\)</span></li>\n                </ul>\n              </li>\n              <li>\n                <p>Tyler's playlist has 36 songs. Noah’s playlist has one quarter as many songs as Tyler's playlist. How many songs are on Noah’s playlist?</p>\n                <ul class=\"list--compressed\">\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36224\">\\(w = 4 \\boldcdot 36\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36267\">\\(w = 36 \\div 4\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36312\">\\(4w = 36\\)</span></li>\n                  <li><span class=\"math math-repaired\" data-png-file-id=\"36365\">\\(\\frac{w}{4} = 36\\)</span></li>\n                </ul>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 4.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>You had $50. You spent 10% of the money on clothes, 20% on games, and the rest on books. How much money was spent on books?</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 12.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>A trash bin has a capacity of 50 gallons. What percentage of its capacity is each amount? Show your reasoning.</p>\n            <ol>\n              <li>5 gallons</li>\n              <li>30 gallons</li>\n              <li>45 gallons</li>\n              <li>100 gallons</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 14.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l07","number":7,"title":"Revisit Percentages","introText":"Let's use equations to find percentages.","activities":[{"title":"7.1: Number Talk: Percentages","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Solve each problem mentally.</p>\n              <ol>\n                <li>Bottle A contains 4 ounces of water, which is 25% of the amount of water in Bottle B. How much water is there in Bottle B?</li>\n                <li>Bottle C contains 150% of the water in Bottle B. How much water is there in Bottle C?</li>\n                <li>Bottle D contains 12 ounces of water. What percentage of the amount of water in Bottle B is this?</li>\n              </ol>\n            </div>"},{"title":"7.2: Representing a Percentage Problem with an Equation","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Answer each question and show your reasoning.</p>\n                  <ol>\n                    <li>\n                      <p>Is 60% of 400 equal to 87?</p>\n                    </li>\n                    <li>\n                      <p>Is 60% of 200 equal to 87?</p>\n                    </li>\n                    <li>Is 60% of 120 equal to 87?\n                    </li>\n                  </ol>\n                </li>\n                <li>60% of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is equal to 87. Write an equation that expresses the relationship between 60%, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, and 87. Solve your equation.\n                </li>\n                <li>\n                  <p>Write an equation to help you find the value of each variable. Solve the equation.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                        <p>60% of <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> is 43.2.</p>\n                      </div>\n                      <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                        <p>38% of <span class=\"math math-repaired\" data-png-file-id=\"108\">\\(e\\)</span> is 190.</p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n              </ol>\n            </div>"},{"title":"7.3: Puppies Grow Up, Revisited","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Puppy A weighs 8 pounds, which is about 25% of its adult weight. What will be the adult weight of Puppy A?</p>\n                </li>\n                <li>\n                  <p>Puppy B weighs 8 pounds, which is about 75% of its adult weight. What will be the adult weight of Puppy B?</p>\n                </li>\n                <li>If you haven’t already, write an equation for each situation. Then, show how you could find the adult weight of each puppy by solving the equation.\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Diego wants to paint his room purple. He bought one gallon of purple paint that is 30% red paint and 70% blue paint. Diego wants to add more blue to the mix so that the paint mixture is 20% red, 80% blue.</p>\n                    <ol>\n                      <li>How much blue paint should Diego add? Test the following possibilities: 0.2 gallons, 0.3 gallons, 0.4 gallons, 0.5 gallons.\n                      </li>\n                      <li>Write an equation in which <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> represents the amount of paint Diego should add.\n                      </li>\n                      <li>Check that the amount of paint Diego should add is a solution to your equation.\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"319\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/505735569\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U6V2 Writing and Solving Equations (Lessons 4–7)</em> available at <a href=\"https://player.vimeo.com/video/505735569\">https://player.vimeo.com/video/505735569</a>.</figcaption>\n              </figure>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>A crew has paved <span class=\"math math-repaired\" data-png-file-id=\"452\">\\(\\frac{3}{4}\\)</span> of a mile of road. If they have completed 50% of the work, how long is the road they are paving?</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>40% of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 35.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>Write an equation that shows the relationship of 40%, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, and 35.</li>\n                    <li>Use your equation to find <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>. Show your reasoning.\n                    </li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Priya has completed 9 exam questions. This is 60% of the questions on the exam.</p>\n            <ol>\n              <li>Write an equation representing this situation. Explain the meaning of any variables you use.\n              </li>\n              <li>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--five-twelfth g--row-1\">\n                      <p>How many questions are on the exam? Show your reasoning.</p>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--row-1 g--seven-twelfth\">\n                      \n                    </div>\n                  </div>\n                </div>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Answer each question. Show your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <p>20% of <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> is 11. What is <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span>?</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <p>75% of <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> is 12. What is <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>?</p>\n                </div>\n              </div>\n              <div class=\"g--row g--row-2\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-2\">\n                  <p>80% of <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span> is 20. What is <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span>?</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-2\">\n                  <p>200% of <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span> is 18. What is <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span>?</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>For the equation <span class=\"math math-repaired\" data-png-file-id=\"35967\">\\(2n - 3 = 7\\)</span></p>\n            <ol>\n              <li>What is the variable?</li>\n              <li>What is the coefficient of the variable?</li>\n              <li>Which of these is the solution to the equation? 2, 3, 5, 7, <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 2.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Which of these is a solution to the equation <span class=\"math math-repaired\" data-png-file-id=\"35966\">\\(\\frac{1}{8}=\\frac{2}{5} \\boldcdot x\\)</span>?</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(\\frac{2}{40}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(\\frac{5}{16}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(\\frac{11}{40}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(\\frac{17}{40}\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 2.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Find the quotients.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35914\">\\(0.009 \\div 0.001\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35958\">\\(0.009 \\div 0.002\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(0.0045 \\div 0.001\\)</span></p>\n              </li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(0.0045 \\div 0.002\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l08","number":8,"title":"Equal and Equivalent","introText":"Let's use diagrams to figure out which expressions are equivalent and which are just sometimes equal.","activities":[{"title":"8.1: Algebra Talk: Solving Equations by Seeing Structure","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find a solution to each equation mentally.</p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39372\">\\(3 + x = 8\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39409\">\\(10 = 12 - x\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39445\">\\(x^2 = 49\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"37015\">\\(\\frac13 x = 6\\)</span></p>\n            </div>"},{"title":"8.2: Using Diagrams to Show That Expressions are Equivalent","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here is a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 4. Notice that the two diagrams are lined up on their left sides.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27770\" data-record-model=\"ImageFile\"><img alt=\"Two tape diagrams.  Top diagram 2 parts, x, 2. Bottom diagram 3 parts x,x,x\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/5vE8sUgQVUA6Nk4zbHihDRRF\">\n                \n              </figure>\n              <p>In each of your drawings below, line up the diagrams on one side.</p>\n              <ol>\n                <li>\n                  <p>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span>, and a separate diagram of <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span>, when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span>, and a separate diagram of <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span>, when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 2.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span>, and a separate diagram of <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span>, when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 1.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                    \n                  </figure>\n                </li>\n                <li>\n                  <p>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span>, and a separate diagram of <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span>, when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 0.</p>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                    \n                  </figure>\n                </li>\n                <li>When are <span class=\"math math-repaired\" data-png-file-id=\"1530\">\\(x+2\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"1639\">\\(3x\\)</span> equal? When are they not equal? Use your diagrams to explain.\n                </li>\n                <li>\n                  <p>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span>, and a separate diagram of <span class=\"math math-repaired\" data-png-file-id=\"3513\">\\(3+x\\)</span>.</p>\n                </li>\n                <li>When are <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"3513\">\\(3+x\\)</span> equal? When are they not equal? Use your diagrams to explain.\n                </li>\n              </ol>\n            </div>"},{"title":"8.3: Identifying Equivalent Expressions","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Here is a list of expressions. Find any pairs of expressions that are equivalent. If you get stuck, try reasoning with diagrams.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--content g--col-1 g--row-1 g--one-sixth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"14135\">\\(a+3\\)</span></p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"6625\">\\(a+a+a\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-2 g--row-1 g--one-sixth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41740\">\\(a \\div \\frac13\\)</span></p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41778\">\\(a \\boldcdot 3\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-3 g--row-1 g--one-sixth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41828\">\\(\\frac13 a\\)</span></p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"1176\">\\(3a\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-4 g--row-1 g--one-sixth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41872\">\\(\\frac{a}{3}\\)</span></p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41920\">\\(1a\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--content g--col-5 g--row-1 g--one-sixth\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span></p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41965\">\\(3+a\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Below are four questions about equivalent expressions. For each one: </p>\n                    <ul class=\"list--compressed\">\n                      <li>Decide whether you think the expressions are equivalent.</li>\n                      <li>Test your guess by choosing numbers for <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> (and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>, if needed).</li>\n                    </ul>\n                    <ol>\n                      <li>Are <span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(\\dfrac{x \\boldcdot  x \\boldcdot  x \\boldcdot  x}{x}\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(x \\boldcdot x \\boldcdot x\\)</span> equivalent expressions?\n                      </li>\n                      <li>Are <span class=\"math math-repaired\" data-png-file-id=\"41453\">\\(\\dfrac{x + x + x + x}{x}\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"41482\">\\(x + x + x\\)</span> equivalent expressions?\n                      </li>\n                      <li>Are <span class=\"math math-repaired\" data-png-file-id=\"41518\">\\(2(x+y)\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"41557\">\\(2x + 2y\\)</span> equivalent expressions?\n                      </li>\n                      <li>Are <span class=\"math math-repaired\" data-png-file-id=\"6537\">\\(2xy\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"41595\">\\(2x \\boldcdot 2y\\)</span> equivalent expressions?\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>We can use diagrams showing lengths of rectangles to see when expressions are equal. For example, the expressions <span class=\"math math-repaired\">\\(x+9\\)</span> and <span class=\"math math-repaired\">\\(4x\\)</span> are equal when <span class=\"math math-repaired\">\\(x\\)</span> is 3, but are not equal for other values of <span class=\"math math-repaired\">\\(x\\)</span>. </p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26870\" data-record-model=\"ImageFile\"><img alt=\"8 tape diagrams of various sizes and various labels on a grid. Each diagram is matched with an expression.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/NpbrNf9HN8hdKKd8H1Bj9ub7\">\n                \n              </figure>\n              <p>Sometimes two expressions are equal for only one particular value of their variable. Other times, they seem to be equal no matter what the value of the variable.</p>\n              <p>Expressions that are always equal for the same value of their variable are called <strong>equivalent expressions</strong>. However, it would be impossible to test every possible value of the variable. How can we know for sure that expressions are equivalent? We use the meaning of operations and properties of operations to know that expressions are equivalent. Here are some examples:</p>\n              <ul class=\"list--compressed\">\n                <li>\n                  <span class=\"math math-repaired\">\\(x+3\\)</span> is equivalent to <span class=\"math math-repaired\">\\(3+x\\)</span> because of the commutative property of addition.</li>\n                <li>\n                  <span class=\"math math-repaired\">\\(4\\boldcdot {y}\\)</span> is equivalent to <span class=\"math math-repaired\">\\(y\\boldcdot 4\\)</span> because of the commutative property of multiplication.</li>\n                <li>\n                  <span class=\"math math-repaired\">\\(a+a+a+a+a\\)</span> is equivalent to <span class=\"math math-repaired\">\\(5\\boldcdot {a}\\)</span> because adding 5 copies of something is the same as multiplying it by 5.</li>\n                <li>\n                  <span class=\"math math-repaired\">\\(b\\div3\\)</span> is equivalent to <span class=\"math math-repaired\">\\(b \\boldcdot {\\frac13}\\)</span> because dividing by a number is the same as multiplying by its reciprocal.</li>\n              </ul>\n              <p>In the coming lessons, we will see how another property, the distributive property, can show that expressions are equivalent.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"36069\">\\(x + 3\\)</span> and a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1683\">\\(2x\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 1.\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                  \n                </figure>\n              </li>\n              <li>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span> and of <span class=\"math math-repaired\" data-png-file-id=\"1683\">\\(2x\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 2.\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                  \n                </figure>\n              </li>\n              <li>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span> and of <span class=\"math math-repaired\" data-png-file-id=\"1683\">\\(2x\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3.\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                  \n                </figure>\n              </li>\n              <li>Draw a diagram of <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span> and of <span class=\"math math-repaired\" data-png-file-id=\"1683\">\\(2x\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 4.\n                <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27566\" data-record-model=\"ImageFile\"><img alt=\"A blank grid with a height of 5 units and a length of 24 units.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/vBWFhTQEUC1zs1CcWBTVSu7r\">\n                  \n                </figure>\n              </li>\n              <li>When are <span class=\"math math-repaired\" data-png-file-id=\"1723\">\\(x+3\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"1683\">\\(2x\\)</span> equal? When are they not equal? Use your diagrams to explain.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>Do <span class=\"math math-repaired\" data-png-file-id=\"2675\">\\(4x\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36054\">\\(15+x\\)</span> have the same value when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 5?\n              </li>\n              <li>\n                <p>Are <span class=\"math math-repaired\" data-png-file-id=\"2675\">\\(4x\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36054\">\\(15+x\\)</span> equivalent expressions? Explain your reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>Check that <span class=\"math math-repaired\" data-png-file-id=\"36070\">\\(2b + b\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36120\">\\(3b\\)</span> have the same value when <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span> is 1, 2, and 3.\n              </li>\n              <li>Do <span class=\"math math-repaired\" data-png-file-id=\"36187\">\\(2b +b\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36104\">\\(3b\\)</span> have the same value for all values of <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>? Explain your reasoning.\n              </li>\n              <li>\n                <p>Are <span class=\"math math-repaired\" data-png-file-id=\"36231\">\\(2b+b\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36104\">\\(3b\\)</span> equivalent expressions?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>80% of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is equal to 100.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>Write an equation that shows the relationship of 80%, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, and 100.</li>\n                    <li>Use your equation to find <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.</li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 7.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>For each story problem, write an equation to represent the problem and then solve the equation. Be sure to explain the meaning of any variables you use.</p>\n            <ol>\n              <li>Jada’s dog was <span class=\"math math-repaired\" data-png-file-id=\"4246\">\\(5\\frac{1}{2}\\)</span> inches tall when it was a puppy. Now her dog is <span class=\"math math-repaired\" data-png-file-id=\"35994\">\\(14\\frac{1}{2}\\)</span> inches taller than that. How tall is Jada’s dog now?\n              </li>\n              <li>Lin picked <span class=\"math math-repaired\" data-png-file-id=\"36055\">\\(9 \\frac{3}{4}\\)</span> pounds of apples, which was 3 times the weight of the apples Andre picked. How many pounds of apples did Andre pick?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 5.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Find these products.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"35780\">\\((2.3) \\boldcdot (1.4)\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"35833\">\\((1.72) \\boldcdot (2.6)\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"35873\">\\((18.2) \\boldcdot (0.2)\\)</span></li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35915\">\\(15 \\boldcdot (1.2)\\)</span></p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 8.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Calculate <span class=\"math math-repaired\" data-png-file-id=\"35911\">\\(141.75 \\div 2.5\\)</span> using a method of your choice. Show or explain your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l09","number":9,"title":"The Distributive Property, Part 1","introText":"Let's use the distributive property to make calculating easier.","activities":[{"title":"9.1: Number Talk: Ways to Multiply","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find each product mentally.</p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39379\">\\(5 \\boldcdot 102\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39416\">\\(5 \\boldcdot 98\\)</span></p>\n              <p><span class=\"math math-repaired\" data-png-file-id=\"39452\">\\(5 \\boldcdot 999\\)</span></p>\n            </div>"},{"title":"9.2: Ways to Represent Area of a Rectangle","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                        <p>Select <strong>all </strong>the expressions that represent the area of the large, outer rectangle in figure A. Explain your reasoning.</p>\n                        <ul class=\"list--compressed\">\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42144\">\\(6 + 3 + 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42186\">\\(6 \\boldcdot 3 + 6 \\boldcdot 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"3520\">\\(6 \\boldcdot 3 + 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42219\">\\(6 \\boldcdot 5\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"3522\">\\(6 (3+2)\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42254\">\\(6 \\boldcdot 3 \\boldcdot 2\\)</span></li>\n                        </ul>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27771\" data-record-model=\"ImageFile\"><img alt=\"One rectangle diagram. Labeled A.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/XeYGBrXN6HnDmuCRBkGsSuBJ\">\n                          \n                        </figure>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                        <p>Select <strong>all </strong>the expressions that represent the area of the shaded rectangle on the left side of figure B. Explain your reasoning.</p>\n                        <ul class=\"list--compressed\">\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(4 \\boldcdot 7 + 4 \\boldcdot 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42339\">\\(4 \\boldcdot 7 \\boldcdot 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"15498\">\\(4 \\boldcdot 5\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(4 \\boldcdot 7 - 4 \\boldcdot 2\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42417\">\\(4(7-2)\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42459\">\\(4(7+2)\\)</span></li>\n                          <li><span class=\"math math-repaired\" data-png-file-id=\"42499\">\\(4 \\boldcdot 2 - 4 \\boldcdot 7\\)</span></li>\n                        </ul>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27772\" data-record-model=\"ImageFile\"><img alt=\"One rectangle diagram. Labeled B.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/cGgt2aJx5e5kpWM1NMeo5E8c\">\n                          \n                        </figure>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n              </ol>\n            </div>"},{"title":"9.3: Distributive Practice","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Complete the table. If you get stuck, skip an entry and come back to it, or consider drawing a diagram of two rectangles that share a side.</p>\n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">  column 1  </th>\n                    <th scope=\"col\">column 2</th>\n                    <th scope=\"col\">column 3</th>\n                    <th scope=\"col\">  column 4  </th>\n                    <th scope=\"col\">  value  </th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"39416\">\\(5 \\boldcdot 98\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40009\">\\(5 (100-2)\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">    \\(5 \\boldcdot 100 - 5 \\boldcdot 2\\)    </span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40075\">\\(500 - 10\\)</span></td>\n                    <td>490</td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40104\">\\(33 \\boldcdot 12\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40138\">\\(33 (10 + 2)\\)</span></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td></td>\n                    <td></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40174\">\\(3 \\boldcdot 10 - 3 \\boldcdot 4\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40202\">\\(30-12\\)</span></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">    \\(100 (0.04 + 0.06)\\)    </span></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td></td>\n                    <td></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40272\">\\(8 \\boldcdot \\frac 1 2 + 8 \\boldcdot \\frac 1 4\\)</span></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40314\">\\(9 + 12\\)</span></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40350\">\\(24 - 16\\)</span></td>\n                    <td></td>\n                  </tr>\n                </tbody>\n              </table>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <ol>\n                      <li>Use the distributive property to write two expressions that equal 360. (There are many correct ways to do this.) \n                      </li>\n                      <li>Is it possible to write an expression like <span class=\"math math-repaired\" data-png-file-id=\"4015\">\\(a(b+c)\\)</span> that equals 360 where <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> is a fraction? Either write such an expression, or explain why it is impossible.\n                      </li>\n                      <li>Is it possible to write an expression like <span class=\"math math-repaired\" data-png-file-id=\"14096\">\\(a(b-c)\\)</span> that equals 360? Either write such an expression, or explain why it is impossible.\n                      </li>\n                      <li>How many ways do you think there are to make 360 using the distributive property?\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A <strong>term</strong> is a single number or variable, or variables and numbers multiplied together. Some examples of terms are 10, <span class=\"math\">\\(8x\\)</span>, <span class=\"math\">\\(ab\\)</span>, and <span class=\"math\">\\(7yz\\)</span>.</p>\n              <p>When we need to do mental calculations, we often come up with ways to make the calculation easier to do mentally.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <p>Suppose we are grocery shopping and need to know how much it will cost to buy 5 cans of beans at 79 cents a can. We may calculate mentally in this way:</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\">\\(5\\boldcdot {79}\\)</span><br>\n                      <span class=\"math math-repaired\">\\(5\\boldcdot {70}+5\\boldcdot {9}\\)</span><br>\n                      <span class=\"math math-repaired\">\\(350+45\\)</span><br>\n                      <span class=\"math math-repaired\">\\(395\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <p>In general, when we multiply two terms (or factors), we can break up one of the factors into parts, multiply each part by the other factor, and then add the products. The result will be the same as the product of the two original factors. When we break up one of the factors and multiply the parts we are using the distributive property.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--row-1 g--two-third\">\n                    <p>The distributive property also works with subtraction. Here is another way to find <span class=\"math math-repaired\">\\(5\\boldcdot 79\\)</span>:</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math math-repaired\">\\(5\\boldcdot 79\\)</span><br>\n                      <span class=\"math math-repaired\">\\(5\\boldcdot {(80-1)}\\)</span><br>\n                      <span class=\"math math-repaired\">\\(400-5\\)</span><br>\n                      <span class=\"math math-repaired\">\\(395\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <p>Select <strong>all</strong> the expressions that represent the area of the large, outer rectangle.</p>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29600\" data-record-model=\"ImageFile\"><img alt=\"Area diagram. A large rectangle partitioned into two smaller rectangles.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/BhTd7JJJs7oocyg7JzT648LH\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(5(2+4)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(5 \\boldcdot 2 + 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(5 \\boldcdot 2 + 5 \\boldcdot 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(5 \\boldcdot 2 \\boldcdot 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(5 + 2+ 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(5 \\boldcdot 6\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Draw and label diagrams that show these two methods for calculating <span class=\"math math-repaired\" data-png-file-id=\"36076\">\\(19 \\boldcdot 50\\)</span>.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--five-twelfth g--row-1\">\n                  <ul>\n                    <li>First find <span class=\"math math-repaired\" data-png-file-id=\"36131\">\\(10\\boldcdot 50\\)</span> and then add <span class=\"math math-repaired\" data-png-file-id=\"36189\">\\(9 \\boldcdot 50\\)</span>.</li>\n                  </ul>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                  <ul>\n                    <li>\n                      <p>First find <span class=\"math math-repaired\" data-png-file-id=\"36234\">\\(20 \\boldcdot 50\\)</span> and then take away 50.</p>\n                    </li>\n                  </ul>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Complete each calculation using the distributive property.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                  <p><span class=\"math math-displayed math-repaired\" data-png-file-id=\"36078\">\\(\\displaystyle 98 \\boldcdot 24\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36130\">\\(\\displaystyle (100-2) \\boldcdot 24\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36182\">\\(\\displaystyle \\ldots\\)</span></p>\n                </div>\n                <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                  <p><span class=\"math math-displayed math-repaired\" data-png-file-id=\"36226\">\\(\\displaystyle 21 \\boldcdot 15\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36268\">\\(\\displaystyle (20 + 1) \\boldcdot 15\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36172\">\\(\\displaystyle \\ldots\\)</span></p>\n                </div>\n                <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                  <p><span class=\"math math-displayed math-repaired\" data-png-file-id=\"36314\">\\(\\displaystyle 0.51 \\boldcdot 40\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36364\">\\(\\displaystyle (0.5 + 0.01) \\boldcdot 40\\)</span> <span class=\"math math-displayed math-repaired\" data-png-file-id=\"36172\">\\(\\displaystyle \\ldots\\)</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>A group of 8 friends go to the movies. A bag of popcorn costs <span>$</span>2.99. How much will it cost to get one bag of popcorn for each friend? Explain how you can calculate this amount mentally.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>On graph paper, draw diagrams of <span class=\"math math-repaired\" data-png-file-id=\"36083\">\\(a+a+a+a\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"3005\">\\(4a\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span> is 1, 2, and 3. What do you notice?\n              </li>\n              <li>Do <span class=\"math math-repaired\" data-png-file-id=\"36083\">\\(a+a+a+a\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"3005\">\\(4a\\)</span> have the same value for any value of <span class=\"math math-repaired\" data-png-file-id=\"81\">\\(a\\)</span>? Explain how you know.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 8.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>120% of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is equal to 78.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>Write an equation that shows the relationship of 120%, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, and 78.</li>\n                    <li>Use your equation to find <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>. Show your reasoning.\n                    </li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 7.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Kiran’s aunt is 17 years older than Kiran.</p>\n            <ol>\n              <li>\n                <p>How old will Kiran’s aunt be when Kiran is:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p>15 years old?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p>30 years old?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> years old?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>How old will Kiran be when his aunt is 60 years old?</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 6.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l10","number":10,"title":"The Distributive Property, Part 2","introText":"Let's use rectangles to understand the distributive property with variables.","activities":[{"title":"10.1: Possible Areas","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>A rectangle has a width of 4 units and a length of <span class=\"math math-repaired\" data-png-file-id=\"40\">\\(m\\)</span> units. Write an expression for the area of this rectangle.</li>\n                <li>\n                  <p>What is the area of the rectangle if <span class=\"math math-repaired\" data-png-file-id=\"40\">\\(m\\)</span> is:</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                        <p>3 units?</p>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                        <p>2.2 units?</p>\n                      </div>\n                      <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"1207\">\\(\\frac15\\)</span> unit?</p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>Could the area of this rectangle be 11 square units? Why or why not? \n                </li>\n              </ol>\n            </div>"},{"title":"10.2: Partitioned Rectangles When Lengths are Unknown","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Here are two rectangles. The length and width of one rectangle are 8 and 5. The width of the other rectangle is 5, but its length is unknown so we labeled it <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                        <p>Write an expression for the sum of the areas of the two rectangles.</p>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27773\" data-record-model=\"ImageFile\"><img alt=\"Two rectangles. The first rectangle has a height of 5 and width of x. The second rectangle has a height of 5 and width of 8.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/SmYH3qeM7uMMavExu4CSSuQY\">\n                          \n                        </figure>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>\n                  <p>The two rectangles can be composed into one larger rectangle as shown.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                        <p>What are the width and length of the new, large rectangle?</p>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                        <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27774\" data-record-model=\"ImageFile\"><img alt=\"Rectangle diagram. The first rectangle has a height of 5 and width of x. Attached is a second rectangle with the same height and width of 8.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/4NQ13F53Utk1jRqDEzw9DVf6\">\n                          \n                        </figure>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>Write an expression for the total area of the large rectangle as the product of its width and its length.\n                </li>\n              </ol>\n            </div>"},{"title":"10.3: Areas of Partitioned Rectangles","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>For each rectangle, write expressions for the length and width and two expressions for the total area. Record them in the table. Check your expressions in each row with your group and discuss any disagreements.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27776\" data-record-model=\"ImageFile\"><img alt=\"Six different sized rectangles labeled A, B, C, D, E, and F.\" class=\"h-max-height--9-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/KAKiXjVrUkqhQESmNCFzj2tC\">\n                \n              </figure>\n              \n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"row\">rectangle</th>\n                    <th scope=\"col\">  width  </th>\n                    <th scope=\"col\">  length  </th>\n                    <th scope=\"col\">area as a product of<br>\n                      width times length</th>\n                    <th scope=\"col\">area as a sum of the areas<br>\n                      of the smaller rectangles</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>A</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>B</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>C</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>D</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>E</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                  <tr>\n                    <th scope=\"row\">\n                      <p>F</p>\n                    </th>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                    <td></td>\n                  </tr>\n                </tbody>\n              </table>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>Here is an area diagram of a rectangle.</p>\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27775\" data-record-model=\"ImageFile\"><img alt=\"Area diagram of a rectangle partition into 4 smaller rectangle.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/8zLBBet9rarAwbobMGJ7ewnt\">\n                      \n                    </figure>\n                    <ol>\n                      <li>Find the lengths <span class=\"math math-repaired\" data-png-file-id=\"1277\">\\(w\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>, and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span>, and the area <span class=\"math math-repaired\" data-png-file-id=\"2\">\\(A\\)</span>. All values are whole numbers.\n                      </li>\n                      <li>Can you find another set of lengths that will work? How many possibilities are there?\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"320\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/513058816\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U6V3 Writing Equivalent Expressions (Lessons 8–11)</em> available at <a href=\"https://player.vimeo.com/video/513058816\">https://player.vimeo.com/video/513058816</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Here is a rectangle.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29605\" data-record-model=\"ImageFile\"><img alt=\"Area diagram. A rectangle partioned vertically into 3 smaller rectangles. \" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/GcxYkZ7ktZ36EhfEHLwaZxcQ\">\n              \n            </figure>\n            <ol>\n              <li>Explain why the area of the large rectangle is <span class=\"math math-repaired\" data-png-file-id=\"36097\">\\(2a + 3a + 4a\\)</span>.\n              </li>\n              <li>Explain why the area of the large rectangle is <span class=\"math math-repaired\" data-png-file-id=\"36157\">\\((2+3+4)a\\)</span>.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Is the area of the shaded rectangle <span class=\"math math-repaired\" data-png-file-id=\"36095\">\\(6(2-m)\\)</span> or <span class=\"math math-repaired\" data-png-file-id=\"36156\">\\(6(m-2)\\)</span>?</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <p>Explain how you know.</p>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29610\" data-record-model=\"ImageFile\"><img alt=\"Area diagram partitioned into two attached rectangles one with a shaded area.\" class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/aW1ZyhB9s4wkPu3aynTfYrmd\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Choose the expressions that do <em>not</em> represent the total area of the rectangle. Select <strong>all </strong>that apply.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29602\" data-record-model=\"ImageFile\"><img alt=\"A rectangle partitioned by a vertical line segment into two smaller rectangles. the vertical side is labeled t and the top horizontal side lengths are labeled 5 and 4.\" class=\"h-max-height--6-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/i8C7gQR8V35gG1KMJQNDsiKg\">\n              \n            </figure>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(5t + 4t\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(t + 5 + 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(9t\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(4 \\boldcdot 5 \\boldcdot t\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(t(5+4)\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression mentally.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36098\">\\(35\\boldcdot 91-35\\boldcdot 89\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36160\">\\(22\\boldcdot 87+22\\boldcdot 13\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36212\">\\(\\frac{9}{11}\\boldcdot \\frac{7}{10}-\\frac{9}{11}\\boldcdot \\frac{3}{10}\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 9.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that are equivalent to <span class=\"math math-repaired\" data-png-file-id=\"13354\">\\(4b\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(b+b+b+b\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(b+4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(2b+2b\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(b \\boldcdot b \\boldcdot b \\boldcdot b\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(b \\div \\frac{1}{4}\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 8.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Solve each equation. Show your reasoning.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"35992\">\\(111=14a\\)</span></p>\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36035\">\\(13.65 = b + 4.88\\)</span></p>\n                </div>\n                <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36099\">\\(c+ \\frac{1}{3} = 5\\frac{1}{8}\\)</span></p>\n                </div>\n              </div>\n              <div class=\"g--row g--row-2\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-2\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36162\">\\(\\frac{2}{5} d = \\frac{17}{4}\\)</span></p>\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36220\">\\(5.16 = 4e\\)</span></p>\n                </div>\n                <div class=\"g--col-3 g--column g--content g--one-third g--row-2\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 4.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Andre ran <span class=\"math math-repaired\" data-png-file-id=\"4246\">\\(5\\frac{1}{2}\\)</span> laps of a track in 8 minutes at a constant speed. It took Andre <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> minutes to run each lap. Select <strong>all</strong> the equations that represent this situation.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(\\left(5\\frac{1}{2}\\right)x = 8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(5 \\frac{1}{2} + x = 8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(5 \\frac{1}{2} - x = 8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(5 \\frac{1}{2} \\div x = 8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(x = 8 \\div \\left(5\\frac{1}{2}\\right)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(x = \\left(5\\frac{1}{2}\\right) \\div 8\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 2.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l11","number":11,"title":"The Distributive Property, Part 3","introText":"Let's practice writing equivalent expressions by using the distributive property.","activities":[{"title":"11.1: The Shaded Region","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A rectangle with dimensions 6 cm and <span class=\"math math-repaired\" data-png-file-id=\"1277\">\\(w\\)</span> cm is partitioned into two smaller rectangles.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                    <div>\n                      <p>Explain why each of these expressions represents the area, in cm<sup>2</sup>, of the shaded region.</p>\n                      <ul>\n                        <li>\n                          <p><span class=\"math math-repaired\" data-png-file-id=\"3534\">\\(6w-24\\)</span></p>\n                        </li>\n                        <li>\n                          <span class=\"math math-repaired\" data-png-file-id=\"3542\">\\(6(w-4)\\)</span>\n                        </li>\n                      </ul>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                    <div>\n                      <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27779\" data-record-model=\"ImageFile\"><img alt='A rectangle with height labeled 6 and total width labeled w. A portion of the width \"w\" is labeled 4.  ' class=\"h-max-height--8-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/eK53F2nqnABaUxXbwxAUitcG\">\n                        \n                      </figure>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"11.2: Matching to Practice Distributive Property","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Match each expression in column 1 to an equivalent expression in column 2. If you get stuck, consider drawing a diagram.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                    <div>\n                      <p>Column 1</p>\n                      <ol>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42158\">\\(a(1+2+3)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42195\">\\(2(12-4)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42229\">\\(12a+3b\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42265\">\\(\\frac23(15a-18)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42304\">\\(6a+10b\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42349\">\\(0.4(5-2.5a)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42391\">\\(2a+3a\\)</span></li>\n                      </ol>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                    <div>\n                      <p>Column 2</p>\n                      <ul>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42428\">\\(3(4a+b)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42468\">\\(12 \\boldcdot 2 - 4 \\boldcdot 2\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42507\">\\(2(3a+5b)\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42546\">\\((2+3)a\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42584\">\\(a+2a+3a\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42621\">\\(10a-12\\)</span></li>\n                        <li><span class=\"math math-repaired\" data-png-file-id=\"42658\">\\(2-a\\)</span></li>\n                      </ul>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"11.3: Writing Equivalent Expressions Using the Distributive Property","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>The distributive property can be used to write equivalent expressions. In each row, use the distributive property to write an equivalent expression. If you get stuck, consider drawing a diagram.</p>\n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">product</th>\n                    <th scope=\"col\">sum or difference</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"39943\">\\(3(3+x)\\)</span></td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td> </td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"39979\">\\(4x-20\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40012\">\\((9-5)x\\)</span></td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td> </td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40048\">\\(4x+7x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40080\">\\(3(2x+1)\\)</span></td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td> </td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40107\">\\(10x-5\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td> </td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40139\">\\(x+2x+3x\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40180\">\\(\\frac12 (x-6)\\)</span></td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40209\">\\(y(3x+4z)\\)</span></td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td> </td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"40241\">\\(2xyz-3yz+4xz\\)</span></td>\n                  </tr>\n                </tbody>\n              </table>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>This rectangle has been cut up into squares of varying sizes. Both small squares have side length 1 unit. The square in the middle has side length <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> units.</p>\n                    <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27780\" data-record-model=\"ImageFile\"><img alt=\"A rectangle tiled with squares of various sizes.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/JkkJyfpBph7SbKP5bCPrHubH\">\n                      \n                    </figure>\n                    <ol>\n                      <li>Suppose that <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3. Find the area of each square in the diagram. Then find the area of the large rectangle.\n                      </li>\n                      <li>Find the side lengths of the large rectangle assuming that <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3. Find the area of the large rectangle by multiplying the length times the width. Check that this is the same area you found before.\n                      </li>\n                      <li>Now suppose that we do not know the value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>. Write an expression for the side lengths of the large rectangle that involves <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>.\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>The distributive property can be used to write a sum as a product, or write a product as a sum. You can always draw a partitioned rectangle to help reason about it, but with enough practice, you should be able to apply the distributive property without making a drawing.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <p>Here are some examples of expressions that are equivalent due to the distributive property.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                    <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle \\begin {align} 9+18&amp;=9(1+2)\\\\ 2(3x+4)&amp;=6x+8\\\\ 2n+3n+n&amp;=n(2+3+1)\\\\ 11b-99a&amp;=11(b-9a)\\\\ k(c+d-e)&amp;=kc+kd-ke\\\\ \\end {align}\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>For each expression, use the distributive property to write an equivalent expression.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"4386\">\\(4(x+2)\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36115\">\\((6+8)\\boldcdot x\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36176\">\\(4(2x+3)\\)</span></li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36223\">\\(6(x+y+z)\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Priya rewrites the expression <span class=\"math math-repaired\" data-png-file-id=\"36124\">\\(8y - 24\\)</span> as <span class=\"math math-repaired\" data-png-file-id=\"36184\">\\(8(y-3)\\)</span>. Han rewrites <span class=\"math math-repaired\" data-png-file-id=\"36233\">\\(8y-24\\)</span> as <span class=\"math math-repaired\" data-png-file-id=\"36273\">\\(2(4y-12)\\)</span>. Are Priya's and Han's expressions each equivalent to <span class=\"math math-repaired\" data-png-file-id=\"36233\">\\(8y-24\\)</span>? Explain your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that are equivalent to <span class=\"math math-repaired\" data-png-file-id=\"36123\">\\(16x + 36\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(16(x+20)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(x(16+36)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(4(4x+9)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(2(8x+18)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(2(8x+36)\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>The area of a rectangle is <span class=\"math math-repaired\" data-png-file-id=\"36134\">\\(30 + 12x\\)</span>. List at least 3 possibilities for the length and width of the rectangle. </p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that are equivalent to <span class=\"math math-repaired\" data-png-file-id=\"36068\">\\(\\frac{1}{2}z\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(z + z\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(z \\div 2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(z \\boldcdot z\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(\\frac{1}{4}z + \\frac{1}{4} z\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(2z\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 8.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>\n                <p>What is the perimeter of a square with side length:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p>3 cm?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p>7 cm?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span> cm?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>If the perimeter of a square is 360 cm, what is its side length?\n              </li>\n              <li>\n                <p>What is the area of a square with side length:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p>3 cm?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p>7 cm?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span> cm?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>If the area of a square is 121 cm<sup>2</sup>, what is its side length?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 6.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Solve each equation.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math\" data-png-file-id=\"35999\">\\(10=4a\\)</span></p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math\" data-png-file-id=\"36039\">\\(5b=17.5\\)</span></p>\n                </div>\n                <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                  <p><span class=\"math\" data-png-file-id=\"36084\">\\(1.036=10c\\)</span></p>\n                </div>\n              </div>\n              <div class=\"g--row g--row-2\">\n                <div class=\"g--col-1 g--column g--content g--one-third g--row-2\">\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                  <p><span class=\"math\" data-png-file-id=\"36151\">\\(0.6d=1.8\\)</span></p>\n                </div>\n                <div class=\"g--col-3 g--column g--content g--one-third g--row-2\">\n                  <p><span class=\"math\" data-png-file-id=\"36206\">\\(15=0.1e\\)</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 5.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l12","number":12,"title":"Meaning of Exponents","introText":"Let’s see how exponents show repeated multiplication.","activities":[{"title":"12.1: Notice and Wonder: Dots and Lines","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>What do you notice? What do you wonder?</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27782\" data-record-model=\"ImageFile\"><img alt=\"A figure of a series of dot branches.\" class=\"h-max-height--21-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/Acgb5THRvTFeTnJiXrHLKtpU\">\n                \n              </figure>\n              \n            </div>"},{"title":"12.2: The Genie’s Offer","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>You find a brass bottle that looks really old. When you rub some dirt off of the bottle, a genie appears! The genie offers you a reward. You must choose one:</p>\n              <ul>\n                <li>\n                  <span>$</span>50,000; or</li>\n                <li>A magical <span>$</span>1 coin. The coin will turn into two coins on the first day. The two coins will turn into four coins on the second day. The four coins will double to 8 coins on the third day. The genie explains the doubling will continue for 28 days.</li>\n              </ul>\n              <ol>\n                <li>The number of coins on the third day will be <span class=\"math math-repaired\" data-png-file-id=\"5619\">\\(2 \\boldcdot 2 \\boldcdot 2\\)</span>. Write an equivalent expression using exponents.</li>\n                <li>What do <span class=\"math math-repaired\" data-png-file-id=\"1145\">\\(2^5\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"4545\">\\(2^6\\)</span> represent in this situation? Evaluate <span class=\"math math-repaired\" data-png-file-id=\"1145\">\\(2^5\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"4545\">\\(2^6\\)</span> without a calculator.</li>\n                <li>How many days would it take for the number of magical coins to exceed <span>$</span>50,000?</li>\n                <li>Will the value of the magical coins exceed a million dollars within the 28 days? Explain or show your reasoning.</li>\n              </ol>\n              <p>Explore the applet. (Why do you think it stops?)</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4293\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4293-1\"></div>\n              </div>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>A scientist is growing a colony of bacteria in a petri dish. She knows that the bacteria are growing and that the number of bacteria doubles every hour.</p>\n                    <p>When she leaves the lab at 5 p.m., there are 100 bacteria in the dish. When she comes back the next morning at 9 a.m., the dish is completely full of bacteria. At what time was the dish half full?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"12.3: Make 81","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <ol>\n                <li>\n                  <p>Here are some expressions. All but one of them equals 16. Find the one that is <em>not</em> equal to 16 and explain how you know.</p>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--column g--one-fourth g--content g--col-1 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"39304\">\\(2^3\\boldcdot 2\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-2 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"2869\">\\(4^2\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-3 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"39335\">\\(\\frac{2^5}{2}\\)</span></p>\n                      </div>\n                      <div class=\"g--column g--one-fourth g--content g--col-4 g--row-1\">\n                        <p><span class=\"math math-repaired\" data-png-file-id=\"1043\">\\(8^2\\)</span></p>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>\n                  <p>Write three expressions containing exponents so that each expression equals 81.</p>\n                </li>\n              </ol>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>When we write an expression like <span class=\"math math-repaired\">\\(2^n\\)</span>, we call <span class=\"math math-repaired\">\\(n\\)</span> the exponent.</p>\n              <p>If <span class=\"math math-repaired\">\\(n\\)</span> is a positive whole number, it tells how many factors of 2 we should multiply to find the value of the expression. For example, <span class=\"math math-repaired\">\\(2^1=2\\)</span>, and <span class=\"math math-repaired\">\\(2^5=2 \\boldcdot 2 \\boldcdot 2 \\boldcdot 2 \\boldcdot 2\\)</span>.</p>\n              <p>There are different ways to say <span class=\"math math-repaired\">\\(2^5\\)</span>. We can say “two raised to the power of five” or “two to the fifth power” or just “two to the fifth.” </p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that are equivalent to 64.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(2^6\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(2^8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(4^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(8^2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(16^4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(32^2\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that equal <span class=\"math math-repaired\" data-png-file-id=\"17936\">\\(3^4\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p>7</p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(4^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p>12</p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p>81</p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p>64</p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(9^2\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p><span class=\"math math-repaired\" data-png-file-id=\"36153\">\\(4^5\\)</span> is equal to 1,024. Evaluate each expression.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"18822\">\\(4^6\\)</span> </p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"1124\">\\(4^4\\)</span> </p>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(4^3\\boldcdot  4^2\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p><span class=\"math math-repaired\" data-png-file-id=\"36147\">\\(6^3=216\\)</span>. Using exponents, write three more expressions whose value is 216.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Find two different ways to rewrite <span class=\"math math-repaired\" data-png-file-id=\"36168\">\\(3xy + 6yz\\)</span> using the distributive property.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 11.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Solve each equation.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36010\">\\(a - 2.01 = 5.5\\)</span></p>\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36045\">\\(b + 2.01 = 5.5\\)</span></p>\n                </div>\n              </div>\n              <div class=\"g--row g--row-2\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-2\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36091\">\\(10c = 13.71\\)</span></p>\n                  \n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-2\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"36166\">\\(100d = 13.71\\)</span></p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 5.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                  <p>Which expressions represent the total area of the large rectangle? Select <strong>all </strong>that apply.</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29601\" data-record-model=\"ImageFile\"><img alt=\"A rectangle partitioned by a horizontal line segment into two smaller rectangles. The bottom horizontal is labeled 6 and the vertical side lengths are labeled n and m.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/3VmJc7tCgTheRmSEcVyPG2cz\">\n                    \n                  </figure>\n                  <p class=\"img-tag-relocated-by-embedder\">​​</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(6(m+n)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(6n + m\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(6n + 6m\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(6mn\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\((n+m)6\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 10.)</span>"},{"title":"Problem 8","html":"<div class=\"im-c-content\">\n            <p>Is each statement true or false? Explain your reasoning.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"35415\">\\(\\frac{45}{100} \\boldcdot 72 = \\frac{45}{72} \\boldcdot 100\\)</span>\n              </li>\n              <li>16% of 250 is equal to 250% of 16\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 3, Lesson 16.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l13","number":13,"title":"Expressions with Exponents","introText":"Let's use the meaning of exponents to decide if equations are true.","activities":[{"title":"13.1: Which One Doesn’t Belong: Twos","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Which one doesn’t belong?</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                    <div>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"4568\">\\(2 \\boldcdot 2 \\boldcdot 2 \\boldcdot 2\\)</span></p>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"40349\">\\(16\\)</span></p>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                    <div>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"4555\">\\(2^4\\)</span></p>\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"2468\">\\(4 \\boldcdot 2\\)</span></p>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"13.2: Is the Equation True?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Decide whether each equation is true or false, and explain how you know.</p>\n              <ol>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"42231\">\\(2^4=2 \\boldcdot 4\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"3550\">\\(3+3+3+3+3=3^5\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"42266\">\\(5^3=5 \\boldcdot 5 \\boldcdot 5\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"42305\">\\(2^3=3^2\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"42351\">\\(16^1=8^2\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(\\frac12 \\boldcdot  \\frac12 \\boldcdot  \\frac12 \\boldcdot  \\frac12 = 4 \\boldcdot \\frac12\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"42436\">\\(\\left( \\frac12 \\right)^4=\\frac{1}{8}\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"3552\">\\(8^2 = 4^3\\)</span></p>\n                </li>\n              </ol>\n            </div>"},{"title":"13.3: What’s Your Reason?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>In each list, find expressions that are equivalent to each other and explain to your partner why they are equivalent. Your partner listens to your explanation. If you disagree, explain your reasoning until you agree. Switch roles for each list. (There may be more than two equivalent expressions in each list.)</p>\n              <ol>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"3776\">\\(5 \\boldcdot 5\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"1145\">\\(2^5\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"2985\">\\(5^2\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"38717\">\\(2 \\boldcdot 5\\)</span></li>\n                  </ol>\n                </li>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"3556\">\\(4^3\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"17936\">\\(3^4\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"2329\">\\(4 \\boldcdot 4 \\boldcdot 4\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"38840\">\\(4+4+4\\)</span></li>\n                  </ol>\n                </li>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43202\">\\(6+6+6\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"3150\">\\(6^3\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"6272\">\\(3^6\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"40585\">\\(3 \\boldcdot 6\\)</span></li>\n                  </ol>\n                </li>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"27166\">\\(11^5\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43241\">\\(11 \\boldcdot 11 \\boldcdot 11 \\boldcdot 11 \\boldcdot 11\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43281\">\\(11 \\boldcdot 5\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43313\">\\(5^{11}\\)</span></li>\n                  </ol>\n                </li>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43347\">\\(\\frac15 \\boldcdot \\frac15 \\boldcdot \\frac15\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43385\">\\(\\left( \\frac15 \\right)^3\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"7351\">\\(\\frac{1}{15}\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"5007\">\\(\\frac{1}{125}\\)</span></li>\n                  </ol>\n                </li>\n                <li>\n                  <ol>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43429\">\\(\\left( \\frac53 \\right)^2\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43476\">\\(\\left( \\frac35 \\right)^2\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"430\">\\(\\frac{10}{6}\\)</span></li>\n                    <li><span class=\"math math-repaired\" data-png-file-id=\"43525\">\\(\\frac{25}{9}\\)</span></li>\n                  </ol>\n                </li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>What is the last digit of <span class=\"math math-repaired\" data-png-file-id=\"43065\">\\(3^{1,000}\\)</span>? Show or explain your reasoning.</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>When working with exponents, the bases don’t have to always be whole numbers. They can also be other kinds of numbers, like fractions, decimals, and even variables. For example, we can use exponents in each of the following ways: </p>\n              <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle \\left(\\frac{2}{3}\\right)^4 = \\frac{2}{3} \\boldcdot \\frac{2}{3} \\boldcdot \\frac{2}{3} \\boldcdot \\frac{2}{3}\\)</span></p>\n              <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle (1.7)^3 = (1.7) \\boldcdot (1.7) \\boldcdot (1.7)\\)</span></p>\n              <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle x^5 = x \\boldcdot x \\boldcdot x \\boldcdot x \\boldcdot x\\)</span></p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> expressions that are equal to <span class=\"math math-repaired\" data-png-file-id=\"36214\">\\(3 \\boldcdot 3 \\boldcdot 3 \\boldcdot 3 \\boldcdot 3\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(3 \\boldcdot 5\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(3^5\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(3^4 \\boldcdot 3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(5 \\boldcdot 3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(5^3\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Noah starts with 0 and then adds the number 5 four times. Diego starts with 1 and then multiplies by the number 5 four times. For each expression, decide whether it is equal to Noah’s result, Diego’s result, or neither.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"15498\">\\(4 \\boldcdot 5\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"32403\">\\(4+5\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36173\">\\(4^5\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"2126\">\\(5^4\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Decide whether each equation is true or false, and explain how you know.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36203\">\\(9 \\boldcdot 9 \\boldcdot 3 = 3^5\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36249\">\\(7 + 7 + 7 = 3 + 3 + 3 + 3 + 3 + 3 + 3\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36297\">\\(\\frac{1}{7} \\boldcdot \\frac{1}{7} \\boldcdot \\frac{1}{7} = \\frac{3}{7}\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36344\">\\(4^1 = 4 \\boldcdot 1\\)</span>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36380\">\\(6 + 6 + 6 = 6^3\\)</span></p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <ol>\n              <li>What is the area of a square with side lengths of <span class=\"math math-repaired\" data-png-file-id=\"3317\">\\(\\frac35\\)</span> units?\n              </li>\n              <li>What is the side length of a square with area <span class=\"math math-repaired\" data-png-file-id=\"936\">\\(\\frac{1}{16}\\)</span> square units?\n              </li>\n              <li>What is the volume of a cube with edge lengths of <span class=\"math math-repaired\" data-png-file-id=\"781\">\\(\\frac23\\)</span> units?\n              </li>\n              <li>What is the edge length of a cube with volume <span class=\"math math-repaired\" data-png-file-id=\"36209\">\\(\\frac{27}{64}\\)</span> cubic units?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that represent the area of the shaded rectangle.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                  <ol>\n                  </ol>\n                </div>\n                <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29604\" data-record-model=\"ImageFile\"><img alt=\"Area diagram. Rectangle partitioned into two smaller rectangles. One rectangle shaded blue.\" class=\"h-max-height--5-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/ZdqVPaVJi15nRLyuBJboWxnH\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(3(10-c)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(3(c-10)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(10(c-3)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(10(3-c)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(30-3c\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p><span class=\"math math-repaired\">\\(30-10c\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 10.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>A ticket at a movie theater costs <span>$</span>8.50. One night, the theater had <span>$</span>29,886 in ticket sales.</p>\n            <ol>\n              <li>\n                <p>Estimate about how many tickets the theater sold. Explain your reasoning.</p>\n              </li>\n              <li>\n                <p>How many tickets did the theater sell? Explain your reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>A fence is being built around a rectangular garden that is <span class=\"math math-repaired\" data-png-file-id=\"35563\">\\(8 \\frac{1}{2}\\)</span> feet by <span class=\"math math-repaired\" data-png-file-id=\"35606\">\\(6 \\frac{1}{3}\\)</span> feet. Fencing comes in panels. Each panel is <span class=\"math math-repaired\" data-png-file-id=\"403\">\\(\\frac{2}{3}\\)</span> of a foot wide. How many panels are needed? Explain or show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 4, Lesson 12.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l14","number":14,"title":"Evaluating Expressions with Exponents","introText":"Let’s find the values of expressions with exponents.","activities":[{"title":"14.1: Revisiting the Cube","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Based on the given information, what other measurements of the square and cube could we find?</p>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4551\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"600\",\"height\":\"450\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":false,\"enableShiftDragZoom\":false,\"showMenuBar\":false,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4551-1\"></div>\n              </div>\n            </div>"},{"title":"14.2: Calculating Surface Area","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A cube has side length 10 inches. Jada says the surface area of the cube is 600 in<sup>2</sup>, and Noah says the surface area of the cube is 3,600 in<sup>2</sup>. Here is how each of them reasoned:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--half g--content g--col-1 g--row-1\">\n                    <p>Jada’s Method:</p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"38240\">\\(6 \\boldcdot 10^2\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41323\">\\(6 \\boldcdot 100\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41351\">\\(600\\)</span></p>\n                  </div>\n                  <div class=\"g--column g--half g--content g--col-2 g--row-1\">\n                    <p>Noah’s Method:</p>\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"38240\">\\(6 \\boldcdot 10^2\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41387\">\\(60^2\\)</span><br>\n                      <span class=\"math math-repaired\" data-png-file-id=\"41422\">\\(3,\\!600\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <p>Do you agree with either of them? Explain your reasoning.</p>\n            </div>"},{"title":"14.3: Row Game: Expression Explosion","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Evaluate the expressions in one of the columns. Your partner will work on the other column. Check with your partner after you finish each row. Your answers in each row should be the same. If your answers aren’t the same, work together to find the error.</p>\n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">column A</th>\n                    <th scope=\"col\">column B</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41651\">\\(5^2+4\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41692\">\\(2^2+25\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41735\">\\(2^4 \\boldcdot 5\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41773\">\\(2^3 \\boldcdot 10\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"4657\">\\(3 \\boldcdot 4^2\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41819\">\\(12 \\boldcdot 2^2\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41866\">\\(20+2^3\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41911\">\\(1+3^3\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"41967\">\\(9 \\boldcdot 2^1\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42012\">\\(3 \\boldcdot 6^1\\)</span></td>\n                  </tr>\n                  <tr>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42060\">\\(\\frac19 \\boldcdot \\left( \\frac12 \\right)^3\\)</span></td>\n                    <td><span class=\"math math-repaired\" data-png-file-id=\"42103\">\\(\\frac18 \\boldcdot \\left( \\frac13 \\right)^2\\)</span></td>\n                  </tr>\n                </tbody>\n              </table>\n              \n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <ol>\n                      <li>\n                        <p>Consider this equation: <span class=\"math math-repaired\" data-png-file-id=\"41412\">\\(\\boxed{\\phantom{3}}^2+\\boxed{\\phantom{3}}^2=\\boxed{\\phantom{3}}^2\\)</span>. An example of 3 different whole numbers that could go in the boxes are 3, 4, and 5, since <span class=\"math math-repaired\" data-png-file-id=\"41447\">\\(\\displaystyle 3^2+4^2=5^2\\)</span>. (That is, <span class=\"math math-repaired\" data-png-file-id=\"13258\">\\(9+16=25\\)</span>.)</p>\n                        <p>Can you find a different set of 3 whole numbers that make the equation true?</p>\n                      </li>\n                      <li>How many sets of 3 different whole numbers can you find?\n                      </li>\n                      <li>Can you find a set of 3 different whole numbers that make this equation true? <span class=\"math math-repaired\" data-png-file-id=\"41484\">\\(\\boxed{\\phantom{3}}^3+\\boxed{\\phantom{3}}^3=\\boxed{\\phantom{3}}^3\\)</span>\n                      </li>\n                      <li>How about this one? <span class=\"math math-repaired\" data-png-file-id=\"41525\">\\(\\boxed{\\phantom{3}}^4+\\boxed{\\phantom{3}}^4=\\boxed{\\phantom{3}}^4\\)</span>\n                      </li>\n                    </ol>\n                    <p>Once you have worked on this a little while, you can understand a problem that is famous in the history of math. (Alas, this space is too small to contain it.) If you are interested, consider doing some further research on <em>Fermat’s Last Theorem</em>.</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Exponents give us a new way to describe operations with numbers, so we need to understand how exponents get along with the other operations we know.</p>\n              <p>When we write <span class=\"math math-repaired\">\\(6 \\boldcdot 4^2\\)</span>, we want to make sure everyone agrees about how to evaluate this. Otherwise some people might multiply first and others compute the exponent first, and different people would get different values for the same expression!</p>\n              <p>Earlier we saw situations in which <span class=\"math math-repaired\">\\(6 \\boldcdot 4^2\\)</span> represented the surface area of a cube with side lengths 4 units. When computing the surface area, we evaluate <span class=\"math math-repaired\">\\(4^2\\)</span> first (or find the area of one face of the cube first) and then multiply the result by 6. In many other expressions that use exponents, the part with an exponent is intended to be evaluated first.</p>\n              <p>To make everyone agree about the value of expressions like <span class=\"math math-repaired\">\\(6 \\boldcdot 4^2\\)</span>, the convention is to <em>evaluate the part of the expression with the exponent first</em>. Here are a couple of examples:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math\">\\( \\begin {align} 6 &amp;\\boldcdot 4^2 \\\\ 6 &amp;\\boldcdot 16 \\\\ &amp;96 \\end {align}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math\">\\( \\begin {align} 45 &amp;+ 5^2 \\\\ 45 &amp;+ 25 \\\\ &amp;70 \\end {align}\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <p>If we want to communicate that 6 and 4 should be multiplied first and then squared, then we can use parentheses to group parts together:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math\">\\( \\begin {align} (6 &amp;\\boldcdot 4)^2 \\\\ &amp;24^2 \\\\ &amp;576 \\end {align}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <p style=\"text-align:center\"><span class=\"math\">\\( \\begin {align} (45 &amp;+ 5)^2 \\\\ &amp;50^2 \\\\ 2,&amp;500 \\end {align}\\)</span></p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Lin says, “I took the number 8, and then multiplied it by the square of 3.” Select <strong>all</strong> the expressions that equal Lin’s answer.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(8 \\boldcdot 3^2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\((8 \\boldcdot 3)^2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(8 \\boldcdot 2^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(3^2 \\boldcdot 8\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(24^2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>72</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36239\">\\(7 + 2^3\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36286\">\\(9 \\boldcdot 3^1\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36335\">\\(20 - 2^4\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36372\">\\(2 \\boldcdot 6^2\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36410\">\\(8 \\boldcdot (\\frac{1}{2})^2\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36448\">\\(\\frac{1}{3} \\boldcdot 3^3\\)</span></p>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36503\">\\((\\frac{1}{5} \\boldcdot 5)^5\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Andre says, “I multiplied 4 by 5, then cubed the result.” Select <strong>all</strong> the expressions that equal Andre’s answer.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(4 \\boldcdot 5^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\((4 \\boldcdot 5)^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\((4 \\boldcdot 5)^2\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(5^3 \\boldcdot 4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(20^3\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">F: \n            <p>500</p>\n          </div>\n          <div class=\"im-c-content\">G: \n            <p>8,000</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Han has 10 cubes, each 5 inches on a side.</p>\n            <ol>\n              <li>Find the total volume of Han’s cubes. Express your answer as an expression using an exponent.\n              </li>\n              <li>Find the total surface area of Han’s cubes. Express your answer as an expression using an exponent.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Priya says that <span class=\"math math-repaired\" data-png-file-id=\"36242\">\\(\\frac{1}{3} \\boldcdot \\frac{1}{3} \\boldcdot \\frac{1}{3} \\boldcdot \\frac{1}{3} = \\frac{4}{3}\\)</span>. Do you agree with Priya? Explain or show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 13.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Answer each question. Show your reasoning.</p>\n            <ol>\n              <li>125% of <span class=\"math math-repaired\" data-png-file-id=\"108\">\\(e\\)</span> is 30. What is <span class=\"math math-repaired\" data-png-file-id=\"108\">\\(e\\)</span>?\n              </li>\n              <li>35% of <span class=\"math math-repaired\" data-png-file-id=\"25\">\\(f\\)</span> is 14. What is <span class=\"math math-repaired\" data-png-file-id=\"25\">\\(f\\)</span>?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 7.)</span>"},{"title":"Problem 7","html":"<div class=\"im-c-content\">\n            <p>Which expressions are solutions to the equation <span class=\"math math-repaired\" data-png-file-id=\"35998\">\\(2.4y = 13.75\\)</span>? Select <strong>all</strong> that apply.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(13.75 - 1.4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\(13.75 \\boldcdot 2.4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(13.75 \\div 2.4\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(\\frac{13.75}{2.4}\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(2.4 \\div 13.75\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 5.)</span>"},{"title":"Problem 8","html":"<div class=\"im-c-content\">\n            <p>Jada explains how she finds <span class=\"math math-repaired\" data-png-file-id=\"35748\">\\(15 \\boldcdot 23\\)</span>:</p>\n            <p>“I know that ten 23s is 230, so five 23s will be half of 230, which is 115.<br>\n              15 is 10 plus 5, so <span class=\"math math-repaired\" data-png-file-id=\"35748\">\\(15 \\boldcdot 23\\)</span> is 230 plus 115, which is 345.”</p>\n            <ol>\n              <li>\n                <p>Do you agree with Jada? Explain.</p>\n              </li>\n              <li>\n                <p>Draw a 15 by 23 rectangle. Partition the rectangle into two rectangles and label them to show Jada’s reasoning.</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 7.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l15","number":15,"title":"Equivalent Exponential Expressions","introText":"Let's investigate expressions with variables and exponents.","activities":[{"title":"15.1: Up or Down?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find the values of <span class=\"math math-repaired\" data-png-file-id=\"6640\">\\(3^x\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"42170\">\\(\\left(\\frac13\\right)^x\\)</span> for different values of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>. What patterns do you notice?</p>\n              <table border=\"1\">\n                <thead>\n                  <tr>\n                    <th scope=\"col\">  <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>  </th>\n                    <th scope=\"col\">  <span class=\"math math-repaired\" data-png-file-id=\"6640\">\\(3^x\\)</span>  </th>\n                    <th scope=\"col\">  <span class=\"math math-repaired\" data-png-file-id=\"failed-conversion\">\\(\\left(\\frac13\\right)^x\\)  </span>\n                    </th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td>1</td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td>2</td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td>3</td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                  <tr>\n                    <td>4</td>\n                    <td> </td>\n                    <td> </td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>"},{"title":"15.2: What's the Value?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Evaluate each expression for the given value of <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span>. </p>\n              <ol>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"1643\">\\(3x^2\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 10</p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"1643\">\\(3x^2\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is <span class=\"math math-repaired\" data-png-file-id=\"3348\">\\(\\frac19\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"41365\">\\(\\frac{x^3}{4}\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 4</p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"41365\">\\(\\frac{x^3}{4}\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is <span class=\"math math-repaired\" data-png-file-id=\"238\">\\(\\frac12\\)</span></p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"3563\">\\(9+x^7\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 1</p>\n                </li>\n                <li>\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"3563\">\\(9+x^7\\)</span> when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is <span class=\"math math-repaired\" data-png-file-id=\"238\">\\(\\frac12\\)</span></p>\n                </li>\n              </ol>\n            </div>"},{"title":"15.3: Exponent Experimentation","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Find a solution to each equation in the list. (Numbers in the list may be a solution to more than one equation, and not all numbers in the list will be used.)</p>\n              <ol>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41536\">\\(64=x^2\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41575\">\\(64=x^3\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41615\">\\(2^x=32\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41657\">\\(x=\\left( \\frac25 \\right)^3\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41705\">\\(\\frac{16}{9}=x^2\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41748\">\\(2\\boldcdot 2^5=2^x\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41795\">\\(2x=2^4\\)</span></li>\n                <li><span class=\"math math-repaired\" data-png-file-id=\"41839\">\\(4^3=8^x\\)</span></li>\n              </ol>\n              <p>List:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-twelfth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"41884\">\\(\\frac{8}{125}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-twelfth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"6544\">\\(\\frac{6}{15}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-twelfth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"366\">\\(\\frac{5}{8}\\)</span></p>\n                  </div>\n                  <div class=\"g--col-4 g--column g--content g--one-twelfth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"8165\">\\(\\frac89\\)</span></p>\n                  </div>\n                  <div class=\"g--col-5 g--column g--content g--one-twelfth g--row-1\">\n                    <p>1</p>\n                  </div>\n                  <div class=\"g--col-6 g--column g--content g--one-twelfth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"4325\">\\(\\frac43\\)</span></p>\n                  </div>\n                  <div class=\"g--col-7 g--column g--content g--one-twelfth g--row-1\">\n                    <p>2</p>\n                  </div>\n                  <div class=\"g--col-8 g--column g--content g--one-twelfth g--row-1\">\n                    <p>3</p>\n                  </div>\n                  <div class=\"g--col-9 g--column g--content g--one-twelfth g--row-1\">\n                    <p>4</p>\n                  </div>\n                  <div class=\"g--col-10 g--column g--content g--one-twelfth g--row-1\">\n                    <p>5</p>\n                  </div>\n                  <div class=\"g--col-11 g--column g--content g--one-twelfth g--row-1\">\n                    <p>6</p>\n                  </div>\n                  <div class=\"g--col-12 g--column g--content g--one-twelfth g--row-1\">\n                    <p>8</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <div class=\"imgrid\">\n                      <div class=\"g--row g--row-1\">\n                        <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                          <p>This fractal is called a Sierpinski Tetrahedron. A tetrahedron is a polyhedron that has four faces. (The plural of tetrahedron is tetrahedra.)</p>\n                          <p>The small tetrahedra form four medium-sized tetrahedra: blue, red, yellow, and green. The medium-sized tetrahedra form one large tetrahedron.</p>\n                        </div>\n                        <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                          <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27784\" data-record-model=\"ImageFile\"><img alt=\"A large tetrahedron composed of various colors of smaller tetrahedra.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/JhnHQcT2Fp1nYTpgW6P2GTMC\">\n                            \n                          </figure>\n                        </div>\n                      </div>\n                    </div>\n                    <ol>\n                      <li>How many small faces does this fractal have? Be sure to include faces you can’t see. Try to find a way to figure this out so that you don’t have to count every face.\n                      </li>\n                      <li>How many small tetrahedra are in the bottom layer, touching the table?\n                      </li>\n                      <li>To make an even bigger version of this fractal, you could take four fractals like the one pictured and put them together. Explain where you would attach the fractals to make a bigger tetrahedron.\n                      </li>\n                      <li>How many small faces would this bigger fractal have? How many small tetrahedra would be in the bottom layer?\n                      </li>\n                      <li>What other patterns can you find?\n                      </li>\n                    </ol>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"321\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/521434518\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U6V4 Expressions with Exponents (Lessons 12–15)</em> available at <a href=\"https://player.vimeo.com/video/521434518\">https://player.vimeo.com/video/521434518</a>.</figcaption>\n              </figure>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression if <span class=\"math math-repaired\" data-png-file-id=\"1393\">\\(x=3\\)</span>.</p>\n            <ol>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"1139\">\\(2^x\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"1244\">\\(x^2\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36266\">\\(1^x\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"28375\">\\(x^1\\)</span></li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36311\">\\(\\left(\\frac12\\right)^x\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression for the given value of each variable.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36261\">\\(2 + x^3\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 3 </p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"1244\">\\(x^2\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is <span class=\"math math-repaired\" data-png-file-id=\"497\">\\(\\frac{1}{2}\\)</span> </p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36307\">\\(3x^2+y\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 5 <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is 3 </p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36358\">\\(10y + x^2\\)</span>, <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 6 <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is 4</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Decide if the expressions have the same value. If not, determine which expression has the larger value.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"1932\">\\(2^3\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"744\">\\(3^2\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36264\">\\(1^{31}\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36308\">\\(31^1\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"2869\">\\(4^2\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"4555\">\\(2^4\\)</span></p>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"11246\">\\(\\left(\\frac12\\right)^3\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"18745\">\\(\\left(\\frac13\\right)^2\\)</span>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Match each equation to its solution.</p>\n          </div>\n          <div class=\"im-c-columns\">\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">A: \n                <p><span class=\"math math-repaired\">\\(7 + x^2 = 16\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">B: \n                <p><span class=\"math math-repaired\">\\(5 - x^2 = 1\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">C: \n                <p><span class=\"math math-repaired\">\\(2 \\boldcdot 2^3 = 2^x\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">D: \n                <p><span class=\"math math-repaired\">\\(\\frac{3^4}{3^x}=27\\)</span></p>\n              </div>\n            </section>\n            <section class=\"im-c-link-menu\">\n              <div class=\"im-c-content\">1: \n                <p><span class=\"math math-repaired\">\\(x=1\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">2: \n                <p><span class=\"math math-repaired\">\\(x=2\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">3: \n                <p><span class=\"math math-repaired\">\\(x=3\\)</span></p>\n              </div>\n              <div class=\"im-c-content\">4: \n                <p><span class=\"math math-repaired\">\\(x=4\\)</span></p>\n              </div>\n            </section>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>An adult pass at the amusement park costs 1.6 times as much as a child’s pass.</p>\n            <ol>\n              <li>\n                <p>How many dollars does an adult pass cost if a child’s pass costs:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                      <p><span>$</span>5?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-2 g--row-1\">\n                      <p><span>$</span>10?</p>\n                    </div>\n                    <div class=\"g--column g--one-third g--content g--col-3 g--row-1\">\n                      <p><span class=\"math math-repaired\" data-png-file-id=\"1277\">\\(w\\)</span> dollars?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>A child’s pass costs <span>$</span>15. How many dollars does an adult pass cost?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 6.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Jada reads 5 pages every 20 minutes. At this rate, how many pages can she read in 1 hour?</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                  <ul>\n                    <li>\n                      <p>Use a double number line to find the answer.</p>\n                    </li>\n                  </ul>\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29501\" data-record-model=\"ImageFile\"><img alt=\"Double number line. Pages read. Time in  minutes.\" class=\"h-max-height--4-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/c1TywVBfBpwXEQG6xAu8XDop\">\n                    \n                  </figure>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                  <ul>\n                    <li>Use a table to find the answer.</li>\n                  </ul>\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"col\">pages<br>\n                          read</th>\n                        <th scope=\"col\">time in<br>\n                          minutes</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <td>5</td>\n                        <td>20</td>\n                      </tr>\n                      <tr>\n                        <td></td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td></td>\n                        <td></td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n            </div>\n            <p>Which strategy do you think is better, and why?</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 2, Lesson 14.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l16","number":16,"title":"Two Related Quantities, Part 1","introText":"Let’s use equations and graphs to describe relationships with ratios.","activities":[{"title":"16.1: Which One Would You Choose?","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Which one would you choose? Be prepared to explain your reasoning.</p>\n              <ul>\n                <li>A 5-pound jug of honey for <span>$</span>15.35</li>\n                <li>Three 1.5-pound jars of honey for <span>$</span>13.05\n                </li>\n              </ul>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27785\" data-record-model=\"ImageFile\"><img alt=\"A 5-pound jug of honey labeled $15.35. Three 1.5-pound jars of honey.\" class=\"h-max-height--11-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/5xsfq5Ew3JK3UjKyDNPZqmnn\">\n                \n              </figure>\n              \n            </div>"},{"title":"16.2: Painting the Set","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Lin needs to mix a specific shade of orange paint for the set of the school play. The color uses 3 parts yellow for every 2 parts red.</p>\n              <ol>\n                <li>\n                  <p>Complete the table to show different combinations of red and yellow paint that will make the shade of orange Lin needs.</p>\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"col\">cups of red paint <span class=\"math math-repaired\" data-png-file-id=\"9538\">\\((r)\\)</span>\n                        </th>\n                        <th scope=\"col\">cups of yellow paint <span class=\"math math-repaired\" data-png-file-id=\"9545\">\\((y)\\)</span>\n                        </th>\n                        <th scope=\"col\">total cups of paint <span class=\"math math-repaired\" data-png-file-id=\"9557\">\\((t)\\)</span>\n                        </th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <td>2</td>\n                        <td>3</td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <td>6</td>\n                        <td> </td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <td> </td>\n                        <td> </td>\n                        <td>20</td>\n                      </tr>\n                      <tr>\n                        <td> </td>\n                        <td>18</td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <td>14</td>\n                        <td> </td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <td>16</td>\n                        <td> </td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <td> </td>\n                        <td> </td>\n                        <td>50</td>\n                      </tr>\n                      <tr>\n                        <td> </td>\n                        <td>42</td>\n                        <td> </td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </li>\n                <li>\n                  <p>Lin notices that the number of cups of red paint is always <span class=\"math math-repaired\" data-png-file-id=\"2302\">\\(\\frac25\\)</span> of the total number of cups. She writes the equation <span class=\"math math-repaired\" data-png-file-id=\"9568\">\\(r=\\frac25 t\\)</span> to describe the relationship. Which is the <strong>independent variable</strong>? Which is the <strong>dependent variable</strong>? Explain how you know.</p>\n                </li>\n                <li>\n                  <p>Write an equation that describes the relationship between <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is the independent variable.</p>\n                </li>\n                <li>\n                  <p>Write an equation that describes the relationship between <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span> is the independent variable.</p>\n                </li>\n                <li>\n                  <p>Use the points in the table to create two graphs that show the relationship between <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span>. Match each relationship to one of the equations you wrote.</p>\n                </li>\n              </ol>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4295\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"609\",\"height\":\"555\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4295-1\"></div>\n              </div>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4296\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"609\",\"height\":\"555\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4296-2\"></div>\n              </div>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <p>A fruit stand sells apples, peaches, and tomatoes. Today, they sold 4 apples for every 5 peaches. They sold 2 peaches for every 3 tomatoes. They sold 132 pieces of fruit in total. How many of each fruit did they sell?</p>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Equations are very useful for describing sets of equivalent ratios. Here is an example.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <p>A pie recipe calls for 3 green apples for every 5 red apples. We can create a table to show some equivalent ratios.</p>\n                    <p>We can see from the table that <span class=\"math math-repaired\">\\(r\\)</span> is always <span class=\"math math-repaired\">\\(\\frac53\\)</span> as large as <span class=\"math math-repaired\">\\(g\\)</span> and that <span class=\"math math-repaired\">\\(g\\)</span> is always <span class=\"math math-repaired\">\\(\\frac35\\)</span> as large as <span class=\"math math-repaired\">\\(r\\)</span>.</p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <table border=\"1\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">green apples (<span class=\"math math-repaired\">\\(g\\)</span>)</th>\n                          <th scope=\"col\">red apples (<span class=\"math math-repaired\">\\(r\\)</span>)</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>3</td>\n                          <td>5</td>\n                        </tr>\n                        <tr>\n                          <td>6</td>\n                          <td>10</td>\n                        </tr>\n                        <tr>\n                          <td>9</td>\n                          <td>15</td>\n                        </tr>\n                        <tr>\n                          <td>12</td>\n                          <td>20</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n              <p>We can write equations to describe the relationship between <span class=\"math math-repaired\">\\(g\\)</span> and <span class=\"math math-repaired\">\\(r\\)</span>.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                    <ul>\n                      <li>\n                        <p>When we know the number of green apples and want to find the number of red apples, we can write:</p>\n                        <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle r=\\frac53g\\)</span></p>\n                        <p>In this equation, if <span class=\"math math-repaired\">\\(g\\)</span> changes, <span class=\"math math-repaired\">\\(r\\)</span> is affected by the change, so we refer to <span class=\"math math-repaired\">\\(g\\)</span> as the <strong>independent variable</strong> and <span class=\"math math-repaired\">\\(r\\)</span> as the <strong>dependent variable</strong>.</p>\n                        <p>We can use this equation with any value of <span class=\"math math-repaired\">\\(g\\)</span> to find <span class=\"math math-repaired\">\\(r\\)</span>. If 270 green apples are used, then <span class=\"math math-repaired\">\\(\\frac53 \\boldcdot (270)\\)</span> or 450 red apples are used.</p>\n                      </li>\n                    </ul>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                    <ul>\n                      <li>\n                        <p>When we know the number of red apples and want to find the number of green apples, we can write:</p>\n                        <p><span class=\"math math-displayed math-repaired\">\\(\\displaystyle g=\\frac35r\\)</span></p>\n                        <p>In this equation, if <span class=\"math math-repaired\">\\(r\\)</span> changes, <span class=\"math math-repaired\">\\(g\\)</span> is affected by the change, so we refer to <span class=\"math math-repaired\">\\(r\\)</span> as the independent variable and <span class=\"math math-repaired\">\\(g\\)</span> as the dependent variable.</p>\n                        <p>We can use this equation with any value of <span class=\"math math-repaired\">\\(r\\)</span> to find <span class=\"math math-repaired\">\\(g\\)</span>. If 275 red apples are used, then <span class=\"math math-repaired\">\\(\\frac35 \\boldcdot (275)\\)</span> or 165 green apples are used.</p>\n                      </li>\n                    </ul>\n                  </div>\n                </div>\n              </div>\n              <p>We can also graph the two equations we wrote to get a visual picture of the relationship between the two quantities.</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26871\" data-record-model=\"ImageFile\"><img alt=\"Two graphs that represent a ratio of two quantities.\" class=\"h-max-height--16-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/SJajJteecmNzrVLpsNTJ4owX\">\n                \n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Here is a graph that shows some values for the number of cups of sugar, <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span>, required to make <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> batches of brownies.</p>\n            <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"29612\" data-record-model=\"ImageFile\"><img alt=\"Eight points plotted on the coordinate plane.\" class=\"h-max-height--14-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/zD4TFy3oiD1RSbQbqjqZUr7e\">\n              \n            </figure>\n            <ol>\n              <li>Complete the table so that the pair of numbers in each column represents the coordinates of a point on the graph.\n                <table border=\"1\">\n                  <thead>\n                    <tr>\n                      <th scope=\"col\"><strong><span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span></strong></th>\n                      <td>  1  </td>\n                      <td>  2  </td>\n                      <td>  3  </td>\n                      <td>  4  </td>\n                      <td>  5  </td>\n                      <td>  6  </td>\n                      <td>  7  </td>\n                    </tr>\n                  </thead>\n                  <tbody>\n                    <tr>\n                      <th scope=\"col\"><strong><span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span></strong></th>\n                      <td></td>\n                      <td></td>\n                      <td></td>\n                      <td></td>\n                      <td></td>\n                      <td></td>\n                      <td></td>\n                    </tr>\n                  </tbody>\n                </table>\n              </li>\n              <li>What does the point <span class=\"math math-repaired\" data-png-file-id=\"15439\">\\((8,4)\\)</span> mean in terms of the amount of sugar and number of batches of brownies?\n              </li>\n              <li>Write an equation that shows the amount of sugar in terms of the number of batches.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Each serving of a certain fruit snack contains 90 calories.</p>\n            <ol>\n              <li>Han wants to know how many calories he gets from the fruit snacks. Write an equation that shows the number of calories, <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span>, in terms of the number of servings, <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span>.</li>\n              <li>Tyler needs some extra calories each day during his sports season. He wants to know how many servings he can have each day if all the extra calories come from the fruit snack. Write an equation that shows the number of servings, <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span>, in terms of the number of calories, <span class=\"math math-repaired\" data-png-file-id=\"98\">\\(c\\)</span>.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Kiran shops for books during a 20% off sale.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--row-1 g--seven-twelfth\">\n                  <ol>\n                    <li>What percent of the original price of a book does Kiran pay during the sale?\n                    </li>\n                    <li>\n                      <p>Complete the table to show how much Kiran pays for books during the sale.</p>\n                    </li>\n                    <li>Write an equation that relates the sale price, <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span>, to the original price <span class=\"math math-repaired\" data-png-file-id=\"65\">\\(p\\)</span>.\n                    </li>\n                    <li>On graph paper, create a graph showing the relationship between the sale price and the original price by plotting the points from the table.</li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-twelfth g--row-1\">\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"col\">original price<br>\n                          in dollars <span class=\"math math-repaired\" data-png-file-id=\"36281\">\\((p)\\)</span>\n                        </th>\n                        <th scope=\"col\">sale price<br>\n                          in dollars <span class=\"math math-repaired\" data-png-file-id=\"36327\">\\((s)\\)</span>\n                        </th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <td>1</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>2</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>3</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>4</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>5</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>6</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>7</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>8</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>9</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>10</td>\n                        <td></td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression when <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 4 and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is 6.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36287\">\\((6-x)^3+y\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36261\">\\(2 + x^3\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36337\">\\(2^x-2y\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36378\">\\(\\left(\\frac{1}{2}\\right)^x\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36416\">\\(1^x + 2^x\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36452\">\\(\\frac{2^x}{x^2}\\)</span></p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 15.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Find <span class=\"math math-repaired\" data-png-file-id=\"35781\">\\((12.34) \\boldcdot (0.7)\\)</span>. Show your reasoning.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 8.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>For each expression, write another division expression that has the same value and that can be used to help find the quotient. Then, find each quotient.</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35919\">\\(302.1 \\div 0.5\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"35961\">\\(12.15 \\div 0.02\\)</span></p>\n              </li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36000\">\\(1.375 \\div 0.11\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l17","number":17,"title":"Two Related Quantities, Part 2","introText":"Let’s use equations and graphs to describe stories with constant speed.","activities":[{"title":"17.1: Walking to the Library","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Lin and Jada each walk at a steady rate from school to the library. Lin can walk 13 miles in 5 hours, and Jada can walk 25 miles in 10 hours. They each leave school at 3:00 and walk <span class=\"math math-repaired\" data-png-file-id=\"8049\">\\(3\\frac14\\)</span> miles to the library. What time do they each arrive?</p>\n            </div>"},{"title":"17.2: The Walk-a-thon","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Diego, Elena, and Andre participated in a walk-a-thon to raise money for cancer research. They each walked at a constant rate, but their rates were different.</p>\n              <ol>\n                <li>Complete the table to show how far each participant walked during the walk-a-thon.\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"col\">time in hours</th>\n                        <th scope=\"col\">miles walked<br>\n                          by Diego</th>\n                        <th scope=\"col\">miles walked<br>\n                          by Elena</th>\n                        <th scope=\"col\">miles walked<br>\n                          by Andre</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <th>1</th>\n                        <td> </td>\n                        <td> </td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <th>2</th>\n                        <td>6</td>\n                        <td> </td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <th> </th>\n                        <td>12</td>\n                        <td>11</td>\n                        <td> </td>\n                      </tr>\n                      <tr>\n                        <th>5</th>\n                        <td> </td>\n                        <td> </td>\n                        <td>17.5</td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </li>\n                <li>How fast was each participant walking in miles per hour?</li>\n                <li>How long did it take each participant to walk one mile?</li>\n                <li>\n                  <p>Graph the progress of each person in the coordinate plane. Use a different color for each participant.</p>\n                  \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4297\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"425\",\"height\":\"630\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":false,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":true,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4297-1\"></div>\n                  </div>\n                </li>\n                <li>\n                  <p>Diego says that <span class=\"math math-repaired\" data-png-file-id=\"9530\">\\(d=3t\\)</span> represents his walk, where <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span> is the distance walked in miles and <span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span> is the time in hours.</p>\n                  <ol>\n                    <li>Explain why <span class=\"math math-repaired\" data-png-file-id=\"9530\">\\(d=3t\\)</span> relates the distance Diego walked to the time it took.</li>\n                    <li>Write two equations that relate distance and time: one for Elena and one for Andre.</li>\n                  </ol>\n                </li>\n                <li>Use the equations you wrote to predict how far each participant would walk, at their same rate, in 8 hours.</li>\n                <li>For Diego’s equation and the equations you wrote, which is the dependent variable and which is the independent variable?</li>\n              </ol>\n            </div>\n          </div>\n          <br>\n          <div class=\"im-c-accordion\">\n            <div class=\"im-c-accordion__item\">\n              <button aria-expanded=\"false\" class=\"im-c-accordion__button js-accordion-toggle\"><svg aria-hidden=\"true\" class=\"im-c-icon im-c-icon--chevron-down\" height=\"12\" viewbox=\"0 0 1200 1200\" width=\"12\"><path d=\"M600.006 989.352l178.709-178.709L1200 389.357l-178.732-178.709L600.006 631.91 178.721 210.648 0 389.369l421.262 421.262 178.721 178.721h.023z\"></path></svg><span>Are you ready for more?</span></button>\n              <div class=\"im-c-accordion__body\">\n                <div class=\"im-c-content\">\n                  <br>\n                  <div class=\"im-c-content\">\n                    <div class=\"imgrid\">\n                      <div class=\"g--row g--row-1\">\n                        <div class=\"g--col-1 g--column g--content g--five-twelfth g--row-1\">\n                          <ol>\n                            <li>Two trains are traveling toward each other, on parallel tracks. Train A is moving at a constant speed of 70 miles per hour. Train B is moving at a constant speed of 50 miles per hour. The trains are initially 320 miles apart. How long will it take them to meet? One way to start thinking about this problem is to make a table. Add as many rows as you like.</li>\n                            <li>\n                              <p>How long will it take a train traveling at 120 miles per hour to go 320 miles?</p>\n                            </li>\n                            <li>Explain the connection between these two problems.\n                            </li>\n                          </ol>\n                        </div>\n                        <div class=\"g--col-2 g--column g--content g--row-1 g--seven-twelfth\">\n                          <table border=\"1\">\n                            <thead>\n                              <tr>\n                                <th scope=\"col\"></th>\n                                <th scope=\"col\">train A</th>\n                                <th scope=\"col\">train B</th>\n                              </tr>\n                            </thead>\n                            <tbody>\n                              <tr>\n                                <th>starting position</th>\n                                <td>0 miles</td>\n                                <td>320 miles</td>\n                              </tr>\n                              <tr>\n                                <th>after 1 hour</th>\n                                <td>70 miles</td>\n                                <td>270 miles</td>\n                              </tr>\n                              <tr>\n                                <th>after 2 hours</th>\n                                <td></td>\n                                <td></td>\n                              </tr>\n                              <tr>\n                                <th></th>\n                                <td></td>\n                                <td></td>\n                              </tr>\n                              <tr>\n                                <th></th>\n                                <td></td>\n                                <td></td>\n                              </tr>\n                            </tbody>\n                          </table>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <figure class=\"embedded-content embedded-content-video-link\" data-embedder-target=\"web\" data-record-id=\"322\" data-record-model=\"VideoLink\"><iframe allowfullscreen=\"true\" frameborder=\"0\" height=\"360\" mozillaallowfullscreen=\"true\" safariallowfullscreen=\"true\" src=\"https://player.vimeo.com/video/530008085\" width=\"640\"></iframe>\n                <figcaption class=\"c-figcaption\">Video <em>VLS G6U6V5 Relationships Between Quantities (Lessons 16–18)</em> available at <a href=\"https://player.vimeo.com/video/530008085\">https://player.vimeo.com/video/530008085</a>.</figcaption>\n              </figure>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>A car is traveling down a road at a constant speed of 50 miles per hour. </p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>Complete the table with the amounts of time it takes the car to travel certain distances, or the distances traveled for certain amounts of time.</li>\n                    <li>\n                      <p>Write an equation that represents the distance traveled by the car, <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span>, for an amount of time, <span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span>.</p>\n                    </li>\n                    <li>In your equation, which is the dependent variable and which is the independent variable?\n                    </li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"col\">time (hours)</th>\n                        <th scope=\"col\">distance (miles)</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <td>2</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td>1.5</td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td><span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span></td>\n                        <td></td>\n                      </tr>\n                      <tr>\n                        <td></td>\n                        <td>50</td>\n                      </tr>\n                      <tr>\n                        <td></td>\n                        <td>300</td>\n                      </tr>\n                      <tr>\n                        <td></td>\n                        <td><span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span></td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--one-sixth g--row-1\">\n                  <p>The graph represents the amount of time in hours it takes a ship to travel various distances in miles.</p>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--five-sixth g--row-1\">\n                  <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"26873\" data-record-model=\"ImageFile\"><img alt=\"A graph of 10 points plotted on the coordinate plane.\" class=\"h-max-height--13-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/5PujLPLrHtTZfZkAz84CULzo\">\n                    \n                  </figure>\n                </div>\n              </div>\n            </div>\n            <ol>\n              <li>Write the coordinates of one point on the graph. What does the point represent?</li>\n              <li>What is the speed of the ship in miles per hour?</li>\n              <li>Write an equation that relates the time, <span class=\"math math-repaired\">\\(t\\)</span>, it takes to travel a given distance, <span class=\"math math-repaired\">\\(d\\)</span>.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>Find a solution to each equation in the list that follows (not all numbers will be used):</p>\n            <ol>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36247\">\\(2^x=8\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36291\">\\(2^x=2\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36342\">\\(x^2=100\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36381\">\\(x^2=\\frac{1}{100}\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36418\">\\(x^1=7\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36464\">\\(2^x\\boldcdot 2^3=2^7\\)</span></p>\n              </li>\n              <li>\n                <p><span class=\"math math-repaired\" data-png-file-id=\"36523\">\\(\\frac{2^x}{2^3}=2^5\\)</span></p>\n              </li>\n            </ol>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--column g--content g--col-1 g--row-1 g--one-twelfth\">\n                  <p>List:</p>\n                </div>\n                <div class=\"g--column g--content g--col-2 g--row-1 g--one-twelfth\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"487\">\\(\\frac{1}{10}\\)</span></p>\n                </div>\n                <div class=\"g--column g--content g--col-3 g--row-1 g--one-twelfth\">\n                  <p><span class=\"math math-repaired\" data-png-file-id=\"1298\">\\(\\frac{1}{3}\\)</span></p>\n                </div>\n                <div class=\"g--column g--content g--col-4 g--row-1 g--one-twelfth\">\n                  <p>1</p>\n                </div>\n                <div class=\"g--column g--content g--col-5 g--row-1 g--one-twelfth\">\n                  <p>2</p>\n                </div>\n                <div class=\"g--column g--content g--col-6 g--row-1 g--one-twelfth\">\n                  <p>3</p>\n                </div>\n                <div class=\"g--column g--content g--col-7 g--row-1 g--one-twelfth\">\n                  <p>4</p>\n                </div>\n                <div class=\"g--column g--content g--col-8 g--row-1 g--one-twelfth\">\n                  <p>5</p>\n                </div>\n                <div class=\"g--column g--content g--col-9 g--row-1 g--one-twelfth\">\n                  <p>7</p>\n                </div>\n                <div class=\"g--column g--content g--col-10 g--row-1 g--one-twelfth\">\n                  <p>8</p>\n                </div>\n                <div class=\"g--column g--content g--col-11 g--row-1 g--one-twelfth\">\n                  <p>10</p>\n                </div>\n                <div class=\"g--column g--content g--col-12 g--row-1 g--one-twelfth\">\n                  <p>16</p>\n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 15.)</span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>Select <strong>all</strong> the expressions that are equivalent to <span class=\"math math-repaired\" data-png-file-id=\"36109\">\\(5x +30x - 15x\\)</span>.</p>\n          </div>\n          <div class=\"im-c-content\">A: \n            <p><span class=\"math math-repaired\">\\(5(x + 6x-3x)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">B: \n            <p><span class=\"math math-repaired\">\\((5+30-15)\\boldcdot x\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">C: \n            <p><span class=\"math math-repaired\">\\(x(5+30x-15x)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">D: \n            <p><span class=\"math math-repaired\">\\(5x(1+6-3)\\)</span></p>\n          </div>\n          <div class=\"im-c-content\">E: \n            <p><span class=\"math math-repaired\">\\(5(x+30x-15x)\\)</span></p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 11.)</span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>Evaluate each expression if <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is 1, <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is 2, and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span> is 3.</p>\n            <ol>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36292\">\\(7x^2-z\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36343\">\\((x+4)^3-y\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36384\">\\(y(x + 3^3)\\)</span>\n              </li>\n              <li>\n                <span class=\"math math-repaired\" data-png-file-id=\"36419\">\\((7-y+z)^2\\)</span>\n              </li>\n              <li><span class=\"math math-repaired\" data-png-file-id=\"36458\">\\(0.241x + x^3\\)</span></li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 6, Lesson 15.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l18","number":18,"title":"More Relationships","introText":"Let’s use graphs and equations to show relationships involving area, volume, and exponents.","activities":[{"title":"18.1: Which One Doesn’t Belong: Graphs","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Which one doesn’t belong?</p>\n              <figure class=\"embedded-content embedded-content-image-file embedded-content-image\" data-embedder-target=\"web\" data-record-id=\"27791\" data-record-model=\"ImageFile\"><img alt='Four points graphed on each of three coordinate planes labeled \"A\", \"B\", \"C\", and \"D\".' class=\"h-max-height--17-lines\" role=\"image\" src=\"https://cms-assets.illustrativemathematics.org/p2Bnrqqx8uTwwp5jtsXoJDre\">\n                \n              </figure>\n              \n            </div>"},{"title":"18.2: Making a Banner","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Mai is creating a rectangular banner to advertise the school play. The material for the banner is sold by the square foot. Mai has enough money to buy 36 square feet of material. She is trying to decide on the length and width of the banner.</p>\n              <ol>\n                <li>\n                  <p>If the length is 6 feet, what is the width?</p>\n                </li>\n                <li>\n                  <p>If the length is 4 feet, what is the width?</p>\n                </li>\n                <li>\n                  <p>If the length is 9 feet, what is the width?</p>\n                </li>\n                <li>\n                  <p>To find different combinations of length and width that give an area of 36 square feet, Mai uses the equation <span class=\"math math-repaired\" data-png-file-id=\"9539\">\\(w=\\frac{36}{\\ell}\\)</span>, where <span class=\"math math-repaired\" data-png-file-id=\"1277\">\\(w\\)</span> is the width and <span class=\"math math-repaired\" data-png-file-id=\"79\">\\(\\ell\\)</span> is the length. Compare your strategy and Mai's method for finding the width. How were they alike or different?</p>\n                </li>\n                <li>\n                  <p>Use several combinations of length and width to create a graph that shows the relationship between the side lengths of various rectangles with area 36 square feet.</p>\n                  \n                  <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4298\" data-record-model=\"GeogebraFile\">\n                    <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"543\",\"height\":\"587\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":false,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":true,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                    <div class=\"ggb-applet-container\" id=\"GeogebraFile-4298-1\"></div>\n                  </div>\n                </li>\n                <li>Explain how the graph describes the relationship between length and width for different rectangles with area 36.</li>\n                <li>Suppose Mai used the equation <span class=\"math math-repaired\" data-png-file-id=\"9548\">\\(\\ell=\\frac{36}{w}\\)</span> to find the length for different values of the width. Would the graph be different if she graphed length on the vertical axis and width on the horizontal axis? Explain how you know.</li>\n              </ol>\n            </div>"},{"title":"18.3: Cereal Boxes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A cereal manufacturer needs to design a cereal box that has a volume of 225 cubic inches and a height that is no more than 15 inches.</p>\n              <ol>\n                <li>The designers know that the volume of a rectangular prism can be calculated by multiplying the area of its base and its height. Complete the table with pairs of values that will make the volume 225 in<sup>3</sup>.\n                  <table border=\"1\">\n                    <thead>\n                      <tr>\n                        <th scope=\"row\">height (in)</th>\n                        <td> </td>\n                        <td>5</td>\n                        <td>9</td>\n                        <td>12</td>\n                        <td> </td>\n                        <td>7<span class=\"math math-repaired\" data-png-file-id=\"238\">\\(\\frac12\\)</span>\n                        </td>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      <tr>\n                        <th scope=\"row\">area of base (in<sup>2</sup>)</th>\n                        <td>75</td>\n                        <td> </td>\n                        <td> </td>\n                        <td> </td>\n                        <td>15</td>\n                        <td> </td>\n                      </tr>\n                    </tbody>\n                  </table>\n                </li>\n                <li>Describe how you found the missing values for the table.</li>\n                <li>Write an equation that shows how the area of the base, <span class=\"math math-repaired\" data-png-file-id=\"2\">\\(A\\)</span>, is affected by changes in the height, <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span>, for different rectangular prisms with volume 225 in<sup>3</sup>.</li>\n                <li>\n                  <p>Plot the ordered pairs from the table on the graph to show the relationship between the area of the base and the height for different boxes box with volume 225 in<sup>3</sup>.</p>\n                </li>\n              </ol>\n              \n              <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4299\" data-record-model=\"GeogebraFile\">\n                <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"572\",\"height\":\"620\",\"enableRightClick\":true,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                <div class=\"ggb-applet-container\" id=\"GeogebraFile-4299-2\"></div>\n              </div>\n            </div>"},{"title":"18.4: Multiplying Mosquitoes","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>A researcher who is studying mosquito populations collects the following data:</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--column g--one-third g--content g--col-1 g--row-1\">\n                    <div>\n                      <table border=\"1\">\n                        <thead>\n                          <tr>\n                            <th scope=\"col\">day in<br>\n                              the study <span class=\"math math-repaired\" data-png-file-id=\"9550\">\\((d)\\)</span>\n                            </th>\n                            <th scope=\"col\">number of<br>\n                              mosquitoes <span class=\"math math-repaired\" data-png-file-id=\"9559\">\\((n)\\)</span>\n                            </th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          <tr>\n                            <td>1</td>\n                            <td>2</td>\n                          </tr>\n                          <tr>\n                            <td>2</td>\n                            <td>4</td>\n                          </tr>\n                          <tr>\n                            <td>3</td>\n                            <td>8</td>\n                          </tr>\n                          <tr>\n                            <td>4</td>\n                            <td>16</td>\n                          </tr>\n                          <tr>\n                            <td>5</td>\n                            <td>32</td>\n                          </tr>\n                        </tbody>\n                      </table>\n                    </div>\n                  </div>\n                  <div class=\"g--column g--two-third g--content g--col-2 g--row-1\">\n                    <div>\n                      <ol>\n                        <li>\n                          <p>The researcher said that, for these five days, the number of mosquitoes, <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span>, can be found with the equation <span class=\"math math-repaired\" data-png-file-id=\"9571\">\\(n = 2^d\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span> is the day in the study. Explain why this equation matches the data.</p>\n                        </li>\n                        <li>\n                          <p>Use the ordered pairs in the table to graph the relationship between number of mosquitoes and day in the study for these five days.</p>\n                          \n                          <div class=\"embedded-content embedded-content-geogebra-file\" data-embedder-target=\"web\" data-record-id=\"4300\" data-record-model=\"GeogebraFile\">\n                            <div class=\"ggb-base-64-data\" data-parameters='{\"width\":\"430\",\"height\":\"510\",\"enableRightClick\":false,\"enableLabelDrags\":false,\"showAlgebraInput\":false,\"showResetIcon\":true,\"enableShiftDragZoom\":false,\"showMenuBar\":true,\"showToolBar\":true,\"allowStyleBar\":false,\"showFullscreenButton\":true,\"ggbBase64\":\"\"}'></div>\n                            <div class=\"ggb-applet-container\" id=\"GeogebraFile-4300-3\"></div>\n                          </div>\n                        </li>\n                        <li>\n                          <p>Describe the graph. Compare how the data, equation, and graph illustrate the relationship between the day in the study and the number of mosquitoes.</p>\n                        </li>\n                        <li>\n                          <p>If the pattern continues, how many mosquitoes will there be on day 6?</p>\n                        </li>\n                      </ol>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Equations can represent relationships between geometric quantities. For instance:</p>\n              <ul>\n                <li>If <span class=\"math math-repaired\">\\(s\\)</span> is the side length of a square, then the area <span class=\"math math-repaired\">\\(A\\)</span> is related to <span class=\"math math-repaired\">\\(s\\)</span> by <span class=\"math math-repaired\">\\(A = s^2\\)</span>.</li>\n                <li>Sometimes the relationships are more specific. For example, the perimeter <span class=\"math math-repaired\">\\(P\\)</span> of a rectangle with length <span class=\"math math-repaired\">\\(l\\)</span> and width <span class=\"math math-repaired\">\\(w\\)</span> is <span class=\"math math-repaired\">\\(P=2l+2w\\)</span>. If we consider only rectangles with a length of 10, then the relationship between the perimeter and the width is <span class=\"math math-repaired\">\\(P = 20 + 2w\\)</span>.</li>\n              </ul>\n              <p>Here is another example of an equation with exponent expressing the relationship between quantities:</p>\n              <ul>\n                <li>\n                  <p>A super ball is dropped from 10 feet. On each successive bounce, it only goes <span class=\"math math-repaired\">\\(\\frac{1}{2}\\)</span> as high as on the previous bounce.</p>\n                  <p>This means that on the first bounce, the ball will bounce 5 feet high, and then on the second bounce it will only go <span class=\"math math-repaired\">\\(2\\frac{1}{2}\\)</span> feet high, and so on. We can represent this situation with an equation to find how high the super ball will bounce after any number of bounces.</p>\n                  <p>To find how high the super ball bounces on the <span class=\"math math-repaired\">\\(n^{\\rm th}\\)</span> bounce, we have to multiply 10 feet (the initial height) by <span class=\"math math-repaired\">\\(\\frac{1}{2}\\)</span> and multiply by <span class=\"math math-repaired\">\\(\\frac{1}{2}\\)</span> again for each bounce thereafter; we need to do this <span class=\"math math-repaired\">\\(n\\)</span> times. So the height, <span class=\"math math-repaired\">\\(h\\)</span>, of the ball on the <span class=\"math math-repaired\">\\(n^{\\rm th}\\)</span> bounce will be <span class=\"math math-repaired\">\\(h =10\\left(\\frac{1}{2}\\right)^n\\)</span>. In this equation, the dependent variable, <span class=\"math math-repaired\">\\(h\\)</span>, is affected by changes in the independent variable, <span class=\"math math-repaired\">\\(n\\)</span>.</p>\n                </li>\n              </ul>\n              <p>Equations and graphs can give us insight into different kinds of relationships between quantities and help us answer questions and solve problems.</p>\n            </div>","glossary":[],"practiceProblems":[{"title":"Problem 1","html":"<div class=\"im-c-content\">\n            <p>Elena is designing a logo in the shape of a parallelogram. She wants the logo to have an area of 12 square inches. She draws bases of different lengths and tries to compute the height for each.</p>\n            <ol>\n              <li>Write an equation Elena can use to find the height, <span class=\"math math-repaired\" data-png-file-id=\"55\">\\(h\\)</span>, for each value of the base, <span class=\"math math-repaired\" data-png-file-id=\"88\">\\(b\\)</span>.</li>\n              <li>Use your equation to find the height of a parallelogram with base <span class=\"math math-repaired\" data-png-file-id=\"7443\">\\(1.5\\)</span> inches.\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 2","html":"<div class=\"im-c-content\">\n            <p>Han is planning to ride his bike 24 miles.</p>\n            <ol>\n              <li>\n                <p>How long will it take if he rides at a rate of:</p>\n                <div class=\"imgrid\">\n                  <div class=\"g--row g--row-1\">\n                    <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                      <p>3 miles per hour?</p>\n                    </div>\n                    <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                      <p>4 miles per hour?</p>\n                    </div>\n                    <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                      <p>6 miles per hour?</p>\n                    </div>\n                  </div>\n                </div>\n              </li>\n              <li>Write an equation that Han can use to find <span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span>, the time it will take to ride 24 miles, if his rate in miles per hour is represented by <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span>.\n              </li>\n              <li>On graph paper, draw a graph that shows <span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span> in terms of <span class=\"math math-repaired\" data-png-file-id=\"832\">\\(r\\)</span> for a 24-mile ride.</li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 3","html":"<div class=\"im-c-content\">\n            <p>The graph of the equation <span class=\"math math-repaired\" data-png-file-id=\"36300\">\\(V=10s^3\\)</span> contains the points <span class=\"math math-repaired\" data-png-file-id=\"36350\">\\((2,80)\\)</span> and <span class=\"math math-repaired\" data-png-file-id=\"36385\">\\((4,640)\\)</span>.</p>\n            <ol>\n              <li>Create a story that is represented by this graph.\n              </li>\n              <li>What do the points mean in the context of your story?\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 4","html":"<div class=\"im-c-content\">\n            <p>You find a brass bottle that looks really old. When you rub some dirt off of the bottle, a genie appears! The genie offers you a reward. You must choose one:</p>\n            <p style=\"text-align:center\"><span>$</span>50,000 or a magical <span>$</span>1 coin.</p>\n            <p>The coin will turn into two coins on the first day. The two coins will turn into four coins on the second day. The four coins will double to 8 coins on the third day. The genie explains the doubling will continue for 28 days.</p>\n            <div class=\"imgrid\">\n              <div class=\"g--row g--row-1\">\n                <div class=\"g--col-1 g--column g--content g--half g--row-1\">\n                  <ol>\n                    <li>\n                      <p>Write an equation that shows the number of coins, <span class=\"math math-repaired\" data-png-file-id=\"749\">\\(n\\)</span>, in terms of the day, <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span>.</p>\n                    </li>\n                    <li>Create a table that shows the number of coins for each day for the first 15 days.</li>\n                    <li>Create a graph for days 7 through 12 that shows how the number of coins grows with each day.</li>\n                  </ol>\n                </div>\n                <div class=\"g--col-2 g--column g--content g--half g--row-1\">\n                  \n                </div>\n              </div>\n            </div>\n          </div>\n          <span class=\"pp-aligned-lesson-address\"></span>"},{"title":"Problem 5","html":"<div class=\"im-c-content\">\n            <p>At a market, 3.1 pounds of peaches cost <span>$</span>7.72. How much did the peaches cost per pound? Explain or show your reasoning. Round your answer to the nearest cent.</p>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>"},{"title":"Problem 6","html":"<div class=\"im-c-content\">\n            <p>Andre set up a lemonade stand last weekend. It cost him <span>$</span>0.15 to make each cup of lemonade, and he sold each cup for <span>$</span>0.35.</p>\n            <ol>\n              <li>\n                <p>If Andre collects <span>$</span>9.80, how many cups did he sell? </p>\n              </li>\n              <li>\n                <p>How much money did it cost Andre to make this amount of lemonade? </p>\n              </li>\n              <li>\n                <p>How much money did Andre make in profit?</p>\n              </li>\n            </ol>\n          </div>\n          <span class=\"pp-aligned-lesson-address\">(From Unit 5, Lesson 13.)</span>\n        </div>\n      </div>\n    </div>\n  </main>"}]},{"uid":"img6.u06.l19","number":19,"title":"Tables, Equations, and Graphs, Oh My!","introText":"Let’s explore some equations from real-world situations.","activities":[{"title":"19.1: Matching Equations and Tables","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Match each equation with a table that represents the same relationship. Be prepared to explain your reasoning.</p>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-fourth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39527\">\\(S - 2 = T\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-fourth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39560\">\\(G = J + 13\\)</span></p>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-fourth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39593\">\\(P = I - 47.50\\)</span></p>\n                  </div>\n                  <div class=\"g--col-4 g--column g--content g--one-fourth g--row-1\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39625\">\\(C + 273.15 = K\\)</span></p>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--one-fourth g--row-2\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39660\">\\(e = 6s\\)</span></p>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-fourth g--row-2\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39691\">\\(m = 8.96V\\)</span></p>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-fourth g--row-2\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39725\">\\(y = \\frac{1}{12}x\\)</span></p>\n                  </div>\n                  <div class=\"g--col-4 g--column g--content g--one-fourth g--row-2\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39755\">\\(t = \\frac{d}{2.5}\\)</span></p>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-3\">\n                  <div class=\"g--col-1 g--column g--content g--one-fourth g--row-3\">\n                    <p><span class=\"math math-repaired\" data-png-file-id=\"39788\">\\(g = 28.35z\\)</span></p>\n                  </div>\n                </div>\n              </div>\n              <div class=\"imgrid\">\n                <div class=\"g--row g--row-1\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                    <p><br>\n                      Table 1:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>20</td>\n                          <td>8</td>\n                        </tr>\n                        <tr>\n                          <td>58.85</td>\n                          <td>23.54</td>\n                        </tr>\n                        <tr>\n                          <td>804</td>\n                          <td>321.6</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-1\">\n                    <p><br>\n                      Table 2:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>5</td>\n                          <td>18</td>\n                        </tr>\n                        <tr>\n                          <td>36</td>\n                          <td>49</td>\n                        </tr>\n                        <tr>\n                          <td>75</td>\n                          <td>88</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-third g--row-1\">\n                    <p><br>\n                      Table 3:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>2.5</td>\n                          <td>22.4</td>\n                        </tr>\n                        <tr>\n                          <td>20</td>\n                          <td>179.2</td>\n                        </tr>\n                        <tr>\n                          <td>75</td>\n                          <td>672</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-2\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-2\">\n                    <p><br>\n                      Table 4:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>20</td>\n                          <td><span class=\"math math-repaired\" data-png-file-id=\"3815\">\\(1\\frac23\\)</span></td>\n                        </tr>\n                        <tr>\n                          <td>36</td>\n                          <td>3</td>\n                        </tr>\n                        <tr>\n                          <td>804</td>\n                          <td>67</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-2\">\n                    <p><br>\n                      Table 5:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>58.85</td>\n                          <td>11.35</td>\n                        </tr>\n                        <tr>\n                          <td>175.5</td>\n                          <td>128</td>\n                        </tr>\n                        <tr>\n                          <td>804</td>\n                          <td>756.5</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-third g--row-2\">\n                    <p><br>\n                      Table 6:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>2.5</td>\n                          <td>275.65</td>\n                        </tr>\n                        <tr>\n                          <td>20</td>\n                          <td>293.15</td>\n                        </tr>\n                        <tr>\n                          <td>58.85</td>\n                          <td>332</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n                <div class=\"g--row g--row-3\">\n                  <div class=\"g--col-1 g--column g--content g--one-third g--row-3\">\n                    <p>Table 7:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>5</td>\n                          <td>3</td>\n                        </tr>\n                        <tr>\n                          <td>20</td>\n                          <td>18</td>\n                        </tr>\n                        <tr>\n                          <td>36</td>\n                          <td>34</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-2 g--column g--content g--one-third g--row-3\">\n                    <p>Table 8:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>2.6</td>\n                          <td>73.71</td>\n                        </tr>\n                        <tr>\n                          <td>20</td>\n                          <td>567</td>\n                        </tr>\n                        <tr>\n                          <td>36</td>\n                          <td>1,020.6</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                  <div class=\"g--col-3 g--column g--content g--one-third g--row-3\">\n                    <p>Table 9:</p>\n                    <table border=\"1\" class=\"c-table-compressed\">\n                      <thead>\n                        <tr>\n                          <th scope=\"col\">independent<br>\n                            variable</th>\n                          <th scope=\"col\">dependent<br>\n                            variable</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr>\n                          <td>2.6</td>\n                          <td>15.6</td>\n                        </tr>\n                        <tr>\n                          <td>36</td>\n                          <td>216</td>\n                        </tr>\n                        <tr>\n                          <td>58.85</td>\n                          <td>353.1</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n            </div>"},{"title":"19.2: Getting to Know an Equation","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>The equations in the previous activity represent situations.</p>\n              <ul>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39527\">\\(S - 2 = T\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"23\">\\(S\\)</span> is the number of sides on a polygon and <span class=\"math math-repaired\" data-png-file-id=\"824\">\\(T\\)</span> is the number of triangles you can draw inside it (from one vertex to the others, without overlapping)</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39560\">\\(G = J + 13\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"27\">\\(G\\)</span> is a day in the Gregorian calendar and <span class=\"math math-repaired\" data-png-file-id=\"99\">\\(J\\)</span> is the same day in the Julian calendar</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39593\">\\(P = I - 47.50\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"2299\">\\(I\\)</span> is the amount of income and <span class=\"math math-repaired\" data-png-file-id=\"9\">\\(P\\)</span> is the profit after <span>$</span>47.50 in expenses</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39625\">\\(C + 273.15 = K\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"7\">\\(C\\)</span> is a temperature in degrees Celsius and <span class=\"math math-repaired\" data-png-file-id=\"1892\">\\(K\\)</span> is the same temperature in Kelvin</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39660\">\\(e = 6s\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"108\">\\(e\\)</span> is the total edge length of a regular tetrahedron and <span class=\"math math-repaired\" data-png-file-id=\"833\">\\(s\\)</span> is the length of one side</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39691\">\\(m = 8.96V\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"122\">\\(V\\)</span> is the volume of a piece of copper and <span class=\"math math-repaired\" data-png-file-id=\"40\">\\(m\\)</span> is its mass</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39725\">\\(y = \\frac{1}{12}x\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"50\">\\(x\\)</span> is the number of eggs and <span class=\"math math-repaired\" data-png-file-id=\"29\">\\(y\\)</span> is how many dozens that makes</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39755\">\\(t = \\frac{d}{2.5}\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"166\">\\(t\\)</span> is the amount of time it takes in seconds to jog a distance of <span class=\"math math-repaired\" data-png-file-id=\"292\">\\(d\\)</span> meters at a constant speed of 2.5 meters per second</li>\n                <li>\n                  <span class=\"math math-repaired\" data-png-file-id=\"39788\">\\(g = 28.35z\\)</span> where <span class=\"math math-repaired\" data-png-file-id=\"39\">\\(g\\)</span> is the mass in grams and <span class=\"math math-repaired\" data-png-file-id=\"280\">\\(z\\)</span> is the same amount in ounces</li>\n              </ul>\n              <p>Your teacher will assign you one of these equations to examine more closely.</p>\n              <ol>\n                <li>Rewrite your equation using words. Use words like product, sum, difference, quotient, and term.\n                </li>\n                <li>\n                  <div class=\"imgrid\">\n                    <div class=\"g--row g--row-1\">\n                      <div class=\"g--col-1 g--column g--content g--one-third g--row-1\">\n                        <p>In the previous activity, you matched equations and tables. Copy the values from the table that matched your assigned equation into the first 3 rows of this table. Make sure to label what each column represents.</p>\n                      </div>\n                      <div class=\"g--col-2 g--column g--content g--row-1 g--two-third\">\n                        <table border=\"1\">\n                          <thead>\n                            <tr>\n                              <th scope=\"col\">independent variable:<br>\n                                ________________________</th>\n                              <th scope=\"col\">dependent variable:<br>\n                                ________________________</th>\n                            </tr>\n                          </thead>\n                          <tbody>\n                            <tr>\n                              <td></td>\n                              <td></td>\n                            </tr>\n                            <tr>\n                              <td></td>\n                              <td></td>\n                            </tr>\n                            <tr>\n                              <td></td>\n                              <td></td>\n                            </tr>\n                            <tr>\n                              <td>60</td>\n                              <td></td>\n                            </tr>\n                            <tr>\n                              <td></td>\n                              <td>300</td>\n                            </tr>\n                          </tbody>\n                        </table>\n                      </div>\n                    </div>\n                  </div>\n                </li>\n                <li>Select one of the first 3 rows of the table and explain what those values mean in this situation.\n                </li>\n                <li>Use your equation to find the values that complete the last 2 rows of the table. Explain your reasoning.\n                </li>\n                <li>On graph paper, create a graph that represents this relationship. Make sure to label your axes.</li>\n              </ol>\n            </div>"},{"title":"19.3: Sharing Your Equation with Others","html":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\">\n              <p>Create a visual display of your assigned relationships that includes:</p>\n              <ul class=\"list--compressed\">\n                <li>your equation along with an explanation of each variable</li>\n                <li>a verbal description of the relationship</li>\n                <li>your table</li>\n                <li>your graph</li>\n              </ul>\n              <p>If you have time, research more about your relationship and add more details or illustrations to help explain the situation.</p>\n            </div>"}],"summaryHtml":"<div class=\"im-c-content\">\n            <div class=\"im-c-content\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </main>","glossary":[],"practiceProblems":[]}]};
